function compactTrim(v,d){return String(+v.toFixed(d))}function compactNum(n){const x=Number(n)||0,a=Math.abs(x);let s=x<0?'-':'';if(!Math.round(a))s='';if(a>=999950000)return s+compactTrim(a/1e9,2)+'B';if(a>=999950)return s+compactTrim(a/1e6,2)+'M';if(a>=1000)return s+compactTrim(a/1e3,1)+'K';return s+Math.round(a).toLocaleString('en-US')}function compactOn(){return !!(typeof SHOP!=='undefined'&&SHOP.compactNumbers)}function fmtQty(n){return (Number(n)||0).toLocaleString('en-US')}
