function figTipInit(){if(window.__figTip)return;window.__figTip=1;const tip=document.createElement('div');tip.id='figTip';tip.className='fig-tip';tip.setAttribute('role','tooltip');document.body.appendChild(tip);let cur=null;const show=el=>{tip.textContent=el.getAttribute('data-full');tip.style.display='block';const r=el.getBoundingClientRect();const w=tip.offsetWidth,h=tip.offsetHeight;let left=r.left+r.width/2-w/2;left=Math.max(8,Math.min(left,innerWidth-w-8));let top=r.top-h-8;if(top<8)top=r.bottom+8;tip.style.left=left+'px';tip.style.top=top+'px'};const hide=()=>{tip.style.display='none';cur=null};document.addEventListener('mouseover',e=>{const el=e.target.closest&&e.target.closest('.fig-compact');if(el&&el!==cur){cur=el;show(el)}});document.addEventListener('mouseout',e=>{const el=e.target.closest&&e.target.closest('.fig-compact');if(el&&!el.contains(e.relatedTarget))hide()});document.addEventListener('focusin',e=>{const el=e.target.closest&&e.target.closest('.fig-compact');if(el){cur=el;show(el)}});document.addEventListener('focusout',hide);window.addEventListener('scroll',hide,true)}
