function backfillActivityTimes(){
  const lists=[state.sales,state.receivings,state.orders,state.layaways,state.refunds,state.payments,state.transfers,state.customers,state.suppliers,state.stocktakes,state.cashbook,state.accountTransfers,state.customerCredits,state.exchanges];
  (state.activity||[]).forEach(a=>{
    if(a.ts)return;
    let raw=null;
    for(const arr of lists){
      const hit=(arr||[]).find(x=>x&&(x.id===a.ref||x.transactionId===a.ref||x.ref===a.ref||x.name===a.ref));
      if(hit&&(hit.date||hit.created)){raw=(hit.date||hit.created)+'T'+(hit.time||'12:00:00');break}
    }
    const t=raw?Date.parse(raw):NaN;
    if(Number.isFinite(t))a.ts=t;else a.date='Earlier';
  });
}
function timeAgo(ts,fallback){
  if(!ts)return fallback||'just now';
  const d=new Date(ts),diff=Date.now()-d.getTime();
  if(!Number.isFinite(diff)||diff<0)return fallback||'just now';
  const sec=Math.floor(diff/1000);
  if(sec<60)return 'just now';
  const min=Math.floor(sec/60);
  if(min<60)return min===1?'1 min ago':min+' mins ago';
  const hr=Math.floor(min/60);
  if(hr<24)return hr===1?'1 hour ago':hr+' hours ago';
  const day=Math.floor(hr/24);
  if(day<=7)return day===1?'1 day ago':day+' days ago';
  return shortDate(d);
}

