let saveQueue=[];
let savePending=false;
let saveTimer=null;
let lastGoodPayload=null;
function ensureSaveUI(){
  let el=document.getElementById('shop360-save-status');
  if(!el){
    el=document.createElement('div');
    el.id='shop360-save-status';
    el.style.cssText='position:fixed;bottom:12px;right:12px;padding:8px 12px;border-radius:10px;font-size:12px;font-weight:600;z-index:10000;pointer-events:none;opacity:0;transition:opacity .2s,transform .2s;transform:translateY(6px);box-shadow:0 4px 12px rgba(0,0,0,.15);';
    document.body.appendChild(el);
  }
  return el;
}
function showSaveStatus(kind,msg){
  const el=ensureSaveUI();
  const colors={saving:'#2563eb',saved:'#16a34a',error:'#dc2626'};
  el.textContent=msg;
  el.style.background=colors[kind]||colors.saving;
  el.style.color='#fff';
  el.style.opacity='1';
  el.style.transform='translateY(0)';
  clearTimeout(el._hide);
  if(kind!=='error') el._hide=setTimeout(()=>{el.style.opacity='0';el.style.transform='translateY(6px)';},1200);
}
async function flushSave(){
  if(savePending) return;
  const payload=saveQueue.pop();
  if(!payload) return;
  while(saveQueue.length>0) saveQueue.pop();
  savePending=true;
  try{
    const r=await fetch('/api/state',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({payload,version:saveVersion,intent:(typeof window!=='undefined'&&window.SHOP360_INTENT)||'general'})
    });
    if(r.status===409){
      const j=await r.json().catch(()=>({}));
      showSaveStatus('error','State changed elsewhere — reloading to sync.');
      saveVersion=typeof j.version==='number'?j.version:saveVersion;
      await load();
      renderAll();
      return;
    }
    if(!r.ok) throw new Error('save failed '+r.status);
    const j=await r.json().catch(()=>({}));
    saveVersion=typeof j.version==='number'?j.version:(saveVersion+1);
    lastGoodPayload=payload;
    showSaveStatus('saved','Saved');
  }catch(e){
    console.error('[shop360] save failed:',e);
    showSaveStatus('error','Save failed — rolling back.');
    if(typeof toast==='function')toast('Could not save changes. They were rolled back — please retry.');
    if(lastGoodPayload){
      try{
        const d=JSON.parse(lastGoodPayload);
        Object.keys(state).forEach(k=>delete state[k]);
        Object.assign(state,d);
      }catch(_){}
    }
    renderAll();
  } finally{
    savePending=false;
    if(saveQueue.length>0) setTimeout(flushSave,0);
  }
}
function persist(){
  try{saveQueue.push(JSON.stringify(state));}catch(e){return false;}
  showSaveStatus('saving','Saving…');
  clearTimeout(saveTimer);
  saveTimer=setTimeout(flushSave,250);
  return true;
}
function migrateSingleShop(){state.migrations=Array.isArray(state.migrations)?state.migrations:[];if(state.migrations.includes('stage30-single-shop-v89'))return;state.products.forEach(p=>(p.variants||[]).forEach(v=>{v.shop=Math.max(0,Number(v.shop)||0);v.warehouse=0;v.batches=Array.isArray(v.batches)?v.batches:[];let excess=v.batches.reduce((n,b)=>n+Math.max(0,Number(b.qty)||0),0)-v.shop;for(let i=v.batches.length-1;i>=0&&excess>0;i--){const b=v.batches[i],take=Math.min(excess,Math.max(0,Number(b.qty)||0));b.qty-=take;excess-=take;}v.batches=v.batches.filter(b=>(Number(b.qty)||0)>0)}));state.transfers=(state.transfers||[]).filter(t=>t.id!=='TR-008');state.activity=(state.activity||[]).filter(a=>a.ref!=='TR-008');state.migrations.push('stage30-single-shop-v89');}
function ensureCustomerCollectionCashbook(){state.cashbook=state.cashbook||[];state.migrations=Array.isArray(state.migrations)?state.migrations:[];if(state.migrations.includes('customer-collections-cashbook-v1'))return;const add=(cid,date,time,method,amount,customer,source)=>{if(!(+amount>0)||state.cashbook.some(e=>e.customerCollectionId===cid))return;state.cashbook.push({id:nextCb(),date,time:time||'',dir:'in',cat:'Customer collection',amount:+amount,method:method||'Cash',note:cid+' · '+(customer||'Walk-in'),customerCollectionId:cid,sourceTransactionId:source||''})};txns().forEach(tx=>{const s=tx.s0||{};if((s.depositMethod||s.paymentMethod)==='Lay-by')return;const a=+(s.cashReceived!=null?s.cashReceived:((+s.paid||0)-(+s.storeCreditUsed||0)));add('CC-SALE-'+tx.id,tx.date,tx.time,s.depositMethod||s.paymentMethod,a,tx.customer,tx.id)});(state.payments||[]).filter(p=>p.method!=='Customer store credit'&&!p.storeCreditUsed&&+p.amount>0).forEach(p=>add('CC-PAY-'+p.id,p.date,p.time,p.method,p.amount,(txns().find(x=>x.id===p.txnId)||{}).customer,p.txnId));(state.layaways||[]).forEach(l=>(l.payments||[]).forEach((x,i)=>{if(x.method!=='Customer store credit'&&+x.amount>0)add('CC-LAY-'+l.id+'-'+i,x.date,x.time,x.method,x.amount,l.customer,l.id)}));state.migrations.push('customer-collections-cashbook-v1');}async function load(){try{const r=await fetch('/api/state');const j=await r.json();saveVersion=typeof j.version==='number'?j.version:0;lastGoodPayload=j&&j.payload?j.payload:null;if(j&&j.payload){const d=JSON.parse(j.payload);['products','sales','receivings','transfers','activity','payments','refunds','categories','brands','migrations','layaways','customers','orders','suppliers','stocktakes','cashbook','expCats','recons','exCats','accounts','accountTransfers','exchanges','customerCredits'].forEach(k=>{if(Array.isArray(d[k]))state[k]=d[k]});if(d.notifRead&&typeof d.notifRead==='object')state.notifRead=d.notifRead;if(d.settings)Object.assign(SHOP,d.settings);if(SHOP.name==='ShoeStock')SHOP.name='Your Shop Name';backfillActivityTimes()}}catch(e){}migrateSingleShop();ensureCustomerCollectionCashbook();persist();} 

