let walletTopUpSubmitting=false;const walletTopUpProcessedForms=new WeakSet();
let customerCollectionSubmitting=false;const customerCollectionProcessedForms=new WeakSet();
function collectionReference(prefix,records){const ds=todayKey().replace(/-/g,'');const start=prefix+'-'+ds+'-';const n=Math.max(0,...(records||[]).map(x=>String(x.id||'')).filter(x=>x.startsWith(start)).map(x=>parseInt(x.slice(start.length),10)||0))+1;return start+String(n).padStart(3,'0')}
