function walletWithdrawalRef(){const ds=todayKey().replace(/-/g,'');const n=Math.max(0,...(state.customerCredits||[]).filter(c=>String(c.id||'').startsWith('WW-'+ds+'-')).map(c=>parseInt(String(c.id).split('-').pop(),10)||0))+1;return 'WW-'+ds+'-'+String(n).padStart(3,'0')}
function openWalletWithdrawal(encodedName){const name=decodeURIComponent(encodedName||'');if(!name){toast('Customer not found.');return}const bal=customerStoreCreditAvailable(name);showModal('Withdraw from customer wallet',`<div class="form-note" style="margin-bottom:12px"><b>${esc(name)}</b><br>Available wallet balance: <b>${money(bal)}</b><br>Withdrawals return prepaid customer funds; they are not business expenses.</div><form onsubmit="reviewWalletWithdrawal(event,'${encodeURIComponent(name)}')"><div class="form-grid"><div class="field"><label>WITHDRAWAL AMOUNT (MWK)</label><input name="amount" type="number" min="1" step="1" max="${bal}" inputmode="numeric" required autofocus placeholder="Enter amount"></div><div class="field"><label>PAYMENT METHOD</label><select name="method" required>${PAYOPTS}</select></div></div><div class="field"><label>REASON / TRANSACTION DETAILS</label><input name="note" maxlength="160" required placeholder="e.g. Customer requested wallet withdrawal"></div><div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary">Review withdrawal</button></div></form>`)}
let _pendingWalletWithdrawal=null,walletWithdrawalSubmitting=false;const walletWithdrawalProcessedForms=new WeakSet();
function consumeWalletForWithdrawal(name,amount,ref){let left=Math.round(+amount||0);if(left<=0)return true;const credits=(state.customerCredits||[]).map((c,i)=>({c,i})).filter(x=>custKey(x.c.customer)===custKey(name)&&x.c.status==='Available').sort((a,b)=>(a.c.date||'').localeCompare(b.c.date||'')||(a.c.time||'').localeCompare(b.c.time||'')||a.i-b.i);for(const x of credits){if(left<=0)break;const c=x.c,available=Math.max(0,(+c.amount||0)-(+c.used||0)),use=Math.min(left,available);c.used=(+c.used||0)+use;left-=use;if(c.used>=c.amount)c.status='Used';c.uses=c.uses||[];c.uses.push({date:todayKey(),time:nowTime(),amount:use,ref})}return left===0}
function reviewWalletWithdrawal(ev,encodedName){ev.preventDefault();const f=ev.currentTarget;if(walletWithdrawalSubmitting||walletWithdrawalProcessedForms.has(f))return;const d=formData(ev),name=decodeURIComponent(encodedName||''),amount=Math.round(+d.amount),method=d.method,allowed=['Cash','Bank Transfer','Airtel Money','TNM Mpamba','POS / Card'],available=customerStoreCreditAvailable(name);if(!name||!(amount>0)||!Number.isSafeInteger(amount)||!allowed.includes(method)){toast('Enter a valid withdrawal amount and payment method.');return}if(!custStats().some(c=>custKey(c.name)===custKey(name))){toast('Customer profile not found.');return}if(amount>available){toast(`Insufficient wallet balance. Available: ${money(available)}.`);return}const accountBalance=balanceAt(cashAll(),method,todayKey());if(amount>accountBalance){toast(`Insufficient balance in ${method}. Available: ${money(accountBalance)}.`);return}_pendingWalletWithdrawal={name,amount,method,note:(d.note||'').trim(),form:f};showModal('Confirm wallet withdrawal',`<div class="form-note">Please review this payment before processing.</div><div class="table-wrap"><table><tbody><tr><th>Customer</th><td>${esc(name)}</td></tr><tr><th>Available wallet balance</th><td>${money(available)}</td></tr><tr><th>Withdrawal amount</th><td><b>${money(amount)}</b></td></tr><tr><th>Paid from</th><td>${esc(method)}</td></tr><tr><th>Reason / details</th><td>${esc(_pendingWalletWithdrawal.note||'—')}</td></tr><tr><th>Cashbook balance after</th><td>${money(accountBalance-amount)}</td></tr></tbody></table></div><div class="form-note">Confirming will deduct the wallet balance and record money out in the selected Cashbook account. This does not count as a business expense or reduce profit.</div><div class="form-actions"><button type="button" class="btn secondary" onclick="_pendingWalletWithdrawal=null;closeModal()">Cancel</button><button type="button" class="btn primary" onclick="commitWalletWithdrawal()">Confirm withdrawal</button></div>`)}
