function commitWalletWithdrawal(){const w=_pendingWalletWithdrawal;if(!w||walletWithdrawalSubmitting)return;const name=w.name,amount=w.amount,method=w.method,available=customerStoreCreditAvailable(name),accountBalance=balanceAt(cashAll(),method,todayKey());if(amount>available){_pendingWalletWithdrawal=null;toast(`Wallet balance changed. Available now: ${money(available)}. Please try again.`);closeModal();return}if(amount>accountBalance){_pendingWalletWithdrawal=null;toast(`Cashbook balance changed. Available in ${method}: ${money(accountBalance)}.`);closeModal();return}if(!['Cash','Bank Transfer','Airtel Money','TNM Mpamba','POS / Card'].includes(method)){toast('Invalid payment method.');return}walletWithdrawalSubmitting=true;const id=walletWithdrawalRef(),cbid=nextCb(),date=todayKey(),time=nowTime(),before=available,note=w.note;const oldCredits=JSON.parse(JSON.stringify(state.customerCredits||[])),oldCashbook=(state.cashbook||[]).slice(),oldActivity=(state.activity||[]).slice();state.customerCredits=state.customerCredits||[];state.cashbook=state.cashbook||[];if(!consumeWalletForWithdrawal(name,amount,'Wallet withdrawal '+id)){state.customerCredits=oldCredits;walletWithdrawalSubmitting=false;toast('Wallet allocation changed. No withdrawal was recorded.');return}const withdrawal={id,customer:name,date,time,amount,used:amount,status:'Completed',type:'wallet_withdrawal',source:'customer_wallet_withdrawal',method,note,cashbookId:cbid,balanceAfter:before-amount};const cash={id:cbid,date,time,dir:'out',cat:'Customer wallet withdrawal',amount,method,note:`${id} · ${name}${note?' · '+note:''}`,walletWithdrawalId:id};state.customerCredits.push(withdrawal);state.cashbook.push(cash);activity('Customer wallet withdrawal',id,'Shop',`${name} · ${money(amount)} · ${method}`);const saved=persist();if(!saved){state.customerCredits=oldCredits;state.cashbook=oldCashbook;state.activity=oldActivity;walletWithdrawalSubmitting=false;toast('Withdrawal was not saved. Wallet and Cashbook balances were restored.');return}walletWithdrawalSubmitting=false;walletWithdrawalProcessedForms.add(w.form);_pendingWalletWithdrawal=null;renderAll();showWalletWithdrawalReceipt(id)}
