function ensureBatches(p){p.variants.forEach(v=>{v.batches=v.batches||[];const have=v.batches.reduce((n,b)=>n+b.qty,0),tot=(+v.shop||0);
if(tot>have){const first=!v.batches.length;v.batches.push({ref:first?'Opening stock':'Adjustment',date:first?'':todayKey(),cost:p.cost,qty:tot-have,orig:tot-have})}
else if(tot<have){let x=have-tot;for(const b of v.batches){const t=Math.min(b.qty,x);b.qty-=t;x-=t;if(x<=0)break}}})}
function variantAvgCost(p,v){ensureBatches(p);const q=v.batches.reduce((n,b)=>n+Math.max(0,b.qty),0),c=v.batches.reduce((n,b)=>n+Math.max(0,b.qty)*b.cost,0);return q>0?c/q:(+p.cost||0)}
function variantStockCost(p,v){ensureBatches(p);return v.batches.reduce((n,b)=>n+Math.max(0,b.qty)*b.cost,0)}
function recalcCost(p){let q=0,c=0;p.variants.forEach(v=>(v.batches||[]).forEach(b=>{q+=b.qty;c+=b.qty*b.cost}));if(q>0)p.cost=Math.round(c/q*10000)/10000}
function addBatch(p,v,q,cost,ref,date,x){ensureBatches(p);v.batches.push({ref,date,cost:Math.round(cost*10000)/10000,qty:q,orig:q,expiry:(x&&x.expiry)||'',lot:(x&&x.lot)||''});v.shop+=q;recalcCost(p)}
function restoreSaleStock(p,v,q,sources,location,ref,skip=0,fallbackCost=0){ensureBatches(p);let remaining=q,offset=Math.max(0,skip),restoredCost=0;const loc='shop';for(const src of (sources||[])){const available=Math.max(0,+src.qty||0);if(offset>=available){offset-=available;continue}const usable=available-offset;offset=0;const take=Math.min(remaining,usable);if(take>0){const cost=+src.cost||0;v.batches.push({ref:`Return · ${src.ref||ref}`,date:todayKey(),cost:Math.round(cost*10000)/10000,qty:take,orig:take,expiry:src.expiry||'',lot:src.lot||''});restoredCost+=take*cost;remaining-=take}if(remaining<=0)break}if(remaining>0){const cost=+fallbackCost||+p.cost||0;v.batches.push({ref:`Return · ${ref}`,date:todayKey(),cost:Math.round(cost*10000)/10000,qty:remaining,orig:remaining,expiry:'',lot:''});restoredCost+=remaining*cost}v[loc]=(v[loc]||0)+q;recalcCost(p);return restoredCost}
const expiryManaged=p=>FEATURES.expiry&&p?.expiryTracked===true;
const isExp=b=>!!(b.expiry&&b.expiry<todayKey());
function sellable(p,v){ensureBatches(p);return v.batches.filter(b=>!expiryManaged(p)||!isExp(b)).reduce((n,b)=>n+b.qty,0)}
function takeFifo(p,v,q,mode){ensureBatches(p);let need=q,tc=0;const src=[];
// FIFO costing follows receipt order. Expired stock is excluded from normal sales;
// explicit expiry write-offs consume expired batches only.
const managed=expiryManaged(p),ord=v.batches.map((b,i)=>({b,i})).filter(x=>mode==='expired'?(managed&&isExp(x.b)):(!managed||!isExp(x.b)));
ord.sort((x,y)=>managed?((x.b.expiry||'9999').localeCompare(y.b.expiry||'9999')||(x.b.date||'').localeCompare(y.b.date||'')||x.i-y.i):((x.b.date||'').localeCompare(y.b.date||'')||x.i-y.i));
for(const {b} of ord){if(need<=0)break;const t=Math.min(Math.max(0,b.qty),need);if(t<=0)continue;b.qty-=t;need-=t;tc+=t*b.cost;src.push({ref:b.ref,qty:t,cost:b.cost,expiry:b.expiry||'',lot:b.lot||'',date:b.date||''})}
if(need>0){const fallback=variantAvgCost(p,v);tc+=need*fallback;src.push({ref:'Unbatched',qty:need,cost:fallback,expiry:'',lot:'',date:''})}recalcCost(p);return{unit:Math.round(tc/Math.max(1,q)*10000)/10000,src}}
function batchTable(p){ensureBatches(p);const g={};p.variants.forEach(v=>v.batches.forEach(b=>{const k=[b.ref,b.date,b.cost,b.expiry||'',b.lot||''].join('|'),o=g[k]=g[k]||{ref:b.ref,date:b.date,cost:b.cost,expiry:b.expiry||'',lot:b.lot||'',orig:0,left:0};o.orig+=b.orig;o.left+=b.qty}));
const anyExp=expiryManaged(p)&&Object.values(g).some(x=>x.expiry),today=todayKey(),soon=new Date();soon.setDate(soon.getDate()+(al().expiryDays??90));const sk=dayKey(soon);
const rows=Object.values(g).filter(x=>x.left>0).sort((a,b)=>(a.expiry||'9999').localeCompare(b.expiry||'9999')||(a.date||'').localeCompare(b.date||'')).map(x=>{const st=!x.expiry?'':x.expiry<today?pill('Expired','#fde3e3','#b43c3c'):x.expiry<=sk?pill('Expires soon','#fff2da','#8b5a13'):'';return `<tr><td>${esc(x.ref)}</td><td>${x.date?fmtDate(x.date):'—'}</td><td>${money(x.cost)}</td>${anyExp?`<td>${esc(x.lot)||'—'}</td><td>${x.expiry?fmtDate(x.expiry):'—'} ${st}</td>`:''}<td>${x.orig}</td><td><b>${x.left}</b></td><td>${p.price?pc((p.price-x.cost)/p.price):'—'}</td></tr>`}).join('');
return `<h3 style="margin:16px 0 6px;font-size:13px">Batches still in stock (${anyExp?'earliest expiry sold first':'sold oldest first'})</h3><div class="table-wrap"><table><thead><tr><th>Source</th><th>Received</th><th>Cost each</th>${anyExp?'<th>Lot</th><th>Expiry</th>':''}<th>Received qty</th><th>Left</th><th>Margin at current price</th></tr></thead><tbody>${rows||'<tr><td colspan="8">No stock left.</td></tr>'}</tbody></table></div>`}
const _vp=viewProduct;viewProduct=function(id){const p=productById(id);_vp(id);const fa=document.getElementById('modalBody').querySelector('.form-actions');if(fa){if(FEATURES.expiry)fa.insertAdjacentHTML('beforebegin',`<div class="form-note" style="margin-top:12px"><b>Expiry tracking:</b> ${expiryManaged(p)?'ON':'OFF'} <button type="button" class="tiny-btn" style="margin-left:8px" onclick="toggleProductExpiry(${p.id})">${expiryManaged(p)?'Turn off':'Turn on'}</button><div class="muted" style="font-size:11px;margin-top:4px">This is a product-level setting and is not determined by the store category. Existing batch dates are retained if tracking is disabled.</div></div>`);fa.insertAdjacentHTML('beforebegin',batchTable(p))}};
function reorderFill(oid,pid){const p=productById(pid);openOrderItem(oid);ai.cat=p.category;ai.model=p.model||p.name;ai.sub=p.sub||'';ai.brand=p.brand||'';aiRender();aiGrids();
const box=document.getElementById('aiColors');box.innerHTML='';[...new Set(p.variants.map(v=>v.color))].forEach(c=>{aiAddColor();const b=box.querySelectorAll('.color-block');b[b.length-1].querySelector('.ai-color').value=c});
const f=document.getElementById('recordForm');if(f){f.elements.price.value=p.price}aiRender();aiNote();toast(`Reorder started for ${p.name}. Enter the pairs and the new cost.`)}
function saveAdjust(e){e.preventDefault();const d=formData(e),p=productById(d.productId),v=variantBySku(p,d.sku),q=Math.round(+d.qty);if(!p||!v||q<1)return;ensureBatches(p);const add=d.dir==='add',have=(+v.shop||0);
if(!add&&q>have){toast('Only '+have+' pairs in stock for that size and colour.');return}
const cost=d.cost===''?variantAvgCost(p,v):+d.cost;let adjustmentValue=0;if(!Number.isFinite(cost)||cost<0){toast('Enter a valid non-negative unit cost.');return}if(add&&expiryManaged(p)&&!d.expiry){toast('Enter the actual expiry date for this expiry-tracked product.');return}if(add){adjustmentValue=Math.round(q*cost*100)/100;addBatch(p,v,q,cost,'Adjustment · '+d.reason,todayKey(),{expiry:expiryManaged(p)?d.expiry:'',lot:expiryManaged(p)?d.lot:''})}else{if(d.reason==='Expired'){const expiredQty=v.batches.filter(b=>isExp(b)).reduce((a,b)=>a+Math.max(0,+b.qty||0),0);if(!expiryManaged(p)||q>expiredQty){toast(`Only ${expiredQty} expired unit(s) are recorded for this item. The write-off was not saved.`);return}}const removed=takeFifo(p,v,q,d.reason==='Expired'?'expired':'sale');adjustmentValue=Math.round(removed.src.reduce((a,b)=>a+b.qty*b.cost,0)*100)/100;v.shop=Math.max(0,v.shop-q)}
const id='RC-'+String(22+state.receivings.length).padStart(3,'0');state.receivings.unshift({id,productId:p.id,sku:v.sku,supplier:d.supplier||'',location:'Shop',qty:add?q:-q,cost:Math.round(add?cost:p.cost),value:adjustmentValue,date:todayKey(),source:'Adjustment',reason:d.reason});
activity('Stock adjustment',id,'Shop',`${add?'+':'−'}${q} pairs · ${d.reason}`);persist();closeModal();renderAll();toast(`${add?'Added':'Removed'} ${q} pair(s). Logged in the stock log.`)}
function orderActual(o){const ref='Order '+o.id,m={},g=pid=>m[pid]=m[pid]||{recv:0,sold:0,rev:0,cost:0,left:0,leftCost:0,leftRev:0};
state.products.forEach(p=>p.variants.forEach(v=>(v.batches||[]).forEach(b=>{if(b.ref!==ref)return;const x=g(p.id);x.recv+=b.orig;x.left+=b.qty;x.leftCost+=b.qty*b.cost;x.leftRev+=b.qty*p.price})));
txns().forEach(t=>t.lines.forEach((l,n)=>{const src=(l.batches||[]).filter(b=>b.ref===ref);if(!src.length)return;const q=src.reduce((a,b)=>a+b.qty,0),f=1-Math.min(1,((t.refQty||{})[n]||0)/l.qty),x=g(l.productId);x.sold+=q*f;x.rev+=l.total*(q/l.qty)*f;x.cost+=src.reduce((a,b)=>a+b.qty*b.cost,0)*f}));
const T=Object.values(m).reduce((a,x)=>{for(const k in x)a[k]=(a[k]||0)+x[k];return a},{recv:0,sold:0,rev:0,cost:0,left:0,leftCost:0,leftRev:0});return{m,T}}
function actualHTML(o,c){const {m,T}=orderActual(o);if(!T.recv)return '<div class="form-note" style="margin-bottom:12px">Nothing received yet. Actual results appear here once pairs arrive and start selling.</div>';
let plan=0;c.lines.forEach((l,li)=>(o.lines[li].variants||[]).forEach(v=>plan+=(v.recv||0)*l.perPair));
const real=T.rev-T.cost,fore=real+(T.leftRev-T.leftCost),d=fore-plan,kv=(a,b,s2)=>`<div style="background:#f5f7fa;border-radius:10px;padding:10px 12px"><div class="muted" style="font-size:10px">${a}</div><div style="font-weight:800;font-size:15px;margin-top:3px">${b}</div>${s2?`<div class="muted" style="font-size:10px;margin-top:2px">${s2}</div>`:''}</div>`;
const rows=Object.entries(m).map(([pid,x])=>{const p=productById(pid),r=x.rev-x.cost;return `<tr><td>${esc(p?p.name:'Item')}</td><td>${x.recv}</td><td>${Math.round(x.sold)}</td><td>${x.left}</td><td class="${r>=0?'positive':''}">${money(r)}</td><td>${x.rev?pc(r/x.rev):'—'}</td></tr>`}).join('');
return `<h3 style="margin:4px 0 8px;font-size:14px">Actual results so far</h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:10px">${kv('Received',`${T.recv} of ${c.qty} pairs`)}${kv('Sold so far',`${Math.round(T.sold)} pairs`,money(T.rev))}${kv('Profit so far',money(real),T.rev?pc(real/T.rev)+' margin':'')}${kv('Still in stock',`${T.left} pairs`,'cost '+money(T.leftCost))}</div>
<div class="form-note" style="margin-bottom:10px">Plan for the pairs received: <b>${money(plan)}</b> profit. If the pairs still in stock sell at today's prices: <b>${money(fore)}</b>, which is <b style="color:${d>=0?'var(--brand)':'#b43c3c'}">${Math.round(Math.abs(d))===0?'on plan':(d>0?'ahead of':'behind')+' plan by '+money(Math.abs(d))}</b>.${planGap(o)?`<div style="margin-top:8px"><button class="btn primary" onclick="fixPlanPrices('${o.id}')">Update Inventory prices to plan</button> <span class="muted">${planGap(o)}</span></div>`:''}</div>
<div class="table-wrap" style="margin-bottom:14px"><table><thead><tr><th>Item</th><th>Received</th><th>Sold</th><th>Left</th><th>Profit so far</th><th>Margin so far</th></tr></thead><tbody>${rows}</tbody></table></div><h3 style="margin:4px 0 8px;font-size:14px">The order as planned</h3>`}
