const capw=w=>w.charAt(0).toUpperCase()+w.slice(1);
function vocabRules(){const t=SHOP.bizType||'general',b=BIZ[t]||BIZ.general,r=[[/\bpairs\b/g,b.many],[/\bPairs\b/g,capw(b.many)],[/\bPAIRS\b/g,b.many.toUpperCase()],[/\bpair\b/g,b.one],[/\bPair\b/g,capw(b.one)],[/\bPAIR\b/g,b.one.toUpperCase()]];
if(t!=='footwear')r.push([/Add shoes to/g,'Add items to'],[/Choose shoes/g,'Choose items'],[/No matching shoes/g,'No matching items'],[/Shoe models/g,'Products'],[/SHOE MODEL/g,'PRODUCT'],[/Shoe model/g,'Product'],[/your shoe business/g,'your business'],[/Search shoe, SKU/g,'Search product, SKU']);return r}
let VR=vocabRules();
const applyRules=t=>VR.reduce((x,[re,to])=>x.replace(re,to),t);
function loc3(n){if(n.__o===undefined||n.__l!==n.nodeValue)n.__o=n.nodeValue;const o=applyRules(n.__o);if(o!==n.nodeValue)n.nodeValue=o;n.__l=o}
function localize(root){if(!root)return;if(root.nodeType===3){const p=root.parentElement;if(!(p&&(/^(SCRIPT|STYLE|TEXTAREA)$/.test(p.tagName)||p.closest('.unit'))))loc3(root);return}
if(root.nodeType!==1)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentElement;return p&&(/^(SCRIPT|STYLE|TEXTAREA)$/.test(p.tagName)||p.closest('.unit'))?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});let n;while(n=w.nextNode())loc3(n);
root.querySelectorAll('[placeholder]').forEach(e=>{if(e.dataset.ph0===undefined||e.dataset.ph1!==e.placeholder)e.dataset.ph0=e.placeholder;const o=applyRules(e.dataset.ph0);if(o!==e.placeholder)e.placeholder=o;e.dataset.ph1=o})}
