let shop=state.products.reduce((a,p)=>a+totalAt(p,'Shop'),0),wh=0,mx=Math.max(...Object.values(catValue()),1);document.getElementById('locationBars').innerHTML=Object.entries(catValue()).sort((a,b)=>b[1]-a[1]).map(([l,n])=>`<div style="margin:18px 0"><div style="display:flex;justify-content:space-between;margin-bottom:7px;font-size:12px"><b>${l}</b><span>${money(n)}</span></div><div style="height:11px;background:#edf1f4;border-radius:10px;overflow:hidden"><div style="width:${n/mx*100}%;height:100%;background:var(--brand);border-radius:10px"></div></div></div>`).join('');
