function inventoryMovementRows(){const rows=[];(state.receivings||[]).forEach(r=>{const p=productById(r.productId),v=variantBySku(p,r.sku);rows.push({date:r.date,ref:r.id,product:p?.name||'Unknown item',variant:v?`${v.color} · ${v.size}`:r.sku,type:r.source==='Adjustment'?'Stock adjustment':'Stock received',qty:r.qty,batch:r.orderId||r.id,cost:r.cost,user:r.user||SHOP.cashier||'Recorded user'})});
(state.sales||[]).forEach(x=>{const p=productById(x.productId),v=variantBySku(p,x.variantSku);rows.push({date:x.date,ref:x.transactionId||x.id,product:p?.name||'Unknown item',variant:v?`${v.color} · ${v.size}`:x.variantSku,type:'Sale',qty:-x.qty,batch:(x.batches||[]).map(b=>b.ref).join(', ')||'FIFO batch',cost:x.unitCost||0,user:x.user||SHOP.cashier||'Recorded user'})});
(state.refunds||[]).forEach(r=>{if(!r.restock)return;const t=tOf(r.txnId);(r.lines||[]).forEach(x=>{const l=t?.lines?.[x.n],p=l&&productById(l.productId),v=l&&variantBySku(p,l.variantSku);rows.push({date:r.date,ref:r.id,product:p?.name||'Unknown item',variant:v?`${v.color} · ${v.size}`:l?.variantSku||'',type:'Customer return',qty:x.qty,batch:'Original FIFO batch restored',cost:l?.unitCost||0,user:r.user||SHOP.cashier||'Recorded user'})})});
return rows.sort((a,b)=>(b.date||'').localeCompare(a.date||''));}
function inventoryBatchRows(){const out=[];state.products.forEach(p=>(p.variants||[]).forEach(v=>(v.batches||[]).forEach((b,i)=>{const rec=(state.receivings||[]).find(r=>r.productId===p.id&&r.sku===v.sku&&((r.orderId&&b.ref==='Order '+r.orderId)||(b.ref==='Receipt '+r.id)||(b.ref===r.id)));out.push({product:p.name,variant:`${v.color} · ${v.size}`,sku:v.sku,batch:b.ref||`Batch ${i+1}`,purchaseRef:rec?.orderId||rec?.id||'',supplier:rec?.supplier||'',date:b.date||rec?.date||'',unitCost:b.cost||0,original:b.orig??b.qty??0,remaining:b.qty||0,lot:b.lot||'',expiry:b.expiry||''})})));return out.sort((a,b)=>(a.date||'').localeCompare(b.date||''));}
function renderInventoryAudit(){const el=document.getElementById('inventoryAuditReport');if(!el)return;const M=inventoryMovementRows(),B=inventoryBatchRows();el.innerHTML=`<details class="inventory-report-group"><summary><span class="inventory-report-title">Stock movements</span><span class="inventory-report-description">Receipts, sales, returns and stock adjustments.</span><span class="inventory-report-chevron" aria-hidden="true">⌄</span></summary><div class="inventory-report-content"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th>Product</th><th>Variant</th><th>Movement</th><th>Qty</th><th>Batch / source</th><th>Unit cost</th><th>Responsible user</th></tr></thead><tbody>${M.slice(0,100).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.ref)}</td><td>${esc(x.product)}</td><td>${esc(x.variant)}</td><td>${esc(x.type)}</td><td style="color:${x.qty<0?'#b43c3c':'#1f7a4d'}"><b>${x.qty>0?'+':''}${x.qty}</b></td><td>${esc(x.batch)}</td><td>${money(x.cost)}</td><td>${esc(x.user)}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">No stock movements recorded.</td></tr>'}</tbody></table></div></div></details><details class="inventory-report-group"><summary><span class="inventory-report-title">FIFO batch position</span><span class="inventory-report-description">Remaining quantities and costs for each stock batch.</span><span class="inventory-report-chevron" aria-hidden="true">⌄</span></summary><div class="inventory-report-content"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Variant</th><th>SKU</th><th>Batch / source</th><th>Purchase ref</th><th>Supplier</th><th>Received</th><th>Landed unit cost</th><th>Remaining</th><th>Lot</th><th>Expiry</th></tr></thead><tbody>${B.slice(0,150).map(x=>`<tr><td>${esc(x.product)}</td><td>${esc(x.variant)}</td><td>${esc(x.sku)}</td><td>${esc(x.batch)}</td><td>${esc(x.purchaseRef||'—')}</td><td>${esc(x.supplier||'—')}</td><td>${x.original}</td><td>${money(x.unitCost)}</td><td><b>${x.remaining}</b></td><td>${esc(x.lot||'—')}</td><td>${x.expiry?fmtDate(x.expiry):'—'}</td></tr>`).join('')||'<tr><td colspan="11" class="empty">No FIFO batch details available.</td></tr>'}</tbody></table></div></div></details><details class="inventory-report-group"><summary><span class="inventory-report-title">Stock valuation by product and variant</span><span class="inventory-report-description">Current stock cost, retail value and estimated gross profit.</span><span class="inventory-report-chevron" aria-hidden="true">⌄</span></summary><div class="inventory-report-content"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Variant</th><th>On hand</th><th>FIFO cost value</th><th>Retail value</th><th>Potential gross profit</th></tr></thead><tbody>${state.products.flatMap(p=>p.variants.map(v=>{const q=(+v.shop||0)+(+v.warehouse||0),c=variantStockCost(p,v),r=q*(+p.price||0);return `<tr><td>${esc(p.name)}</td><td>${esc(v.color)} · ${esc(v.size)}</td><td>${q}</td><td>${money(c)}</td><td>${money(r)}</td><td>${money(r-c)}</td></tr>`})).join('')||'<tr><td colspan="6" class="empty">No inventory.</td></tr>'}</tbody></table></div></div></details>
<details class="inventory-report-group"><summary><span class="inventory-report-title">Low-stock and out-of-stock variants</span><span class="inventory-report-description">Variants at or below the current two-pair threshold.</span><span class="inventory-report-chevron" aria-hidden="true">⌄</span></summary><div class="inventory-report-content"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Variant</th><th>On hand</th><th>Threshold</th><th>Status</th></tr></thead><tbody>${state.products.flatMap(p=>p.variants.map(v=>({p,v,q:(+v.shop||0)+(+v.warehouse||0)})).filter(x=>x.q<=2).map(x=>`<tr><td>${esc(x.p.name)}</td><td>${esc(x.v.color)} · ${esc(x.v.size)}</td><td>${x.q}</td><td>2</td><td>${x.q===0?'Out of stock':'Low stock'}</td></tr>`)).join('')||'<tr><td colspan="5" class="empty">No low or out-of-stock variants.</td></tr>'}</tbody></table></div></div></details>
<details class="inventory-report-group"><summary><span class="inventory-report-title">Product performance</span><span class="inventory-report-description">Units sold, sales value, estimated cost and gross profit.</span><span class="inventory-report-chevron" aria-hidden="true">⌄</span></summary><div class="inventory-report-content"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units sold</th><th>Sales value</th><th>Estimated COGS</th><th>Estimated gross profit</th></tr></thead><tbody>${(()=>{const m={};(state.sales||[]).forEach(x=>{const p=productById(x.productId),k=p?.name||'Unknown item',o=m[k]=m[k]||{q:0,s:0,c:0};o.q+=x.qty;o.s+=x.total;o.c+=x.qty*(x.unitCost??p?.cost??0)});return Object.entries(m).sort((a,b)=>b[1].s-a[1].s).map(([k,x])=>`<tr><td>${esc(k)}</td><td>${x.q}</td><td>${money(x.s)}</td><td>${money(x.c)}</td><td>${money(x.s-x.c)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No sales recorded.</td></tr>'})()}</tbody></table></div></div></details>
<details class="inventory-report-group"><summary><span class="inventory-report-title">Batch movement allocations</span><span class="inventory-report-description">Trace sales and returns to their original stock batches.</span><span class="inventory-report-chevron" aria-hidden="true">⌄</span></summary><div class="inventory-report-content"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Sale / return ref</th><th>Product</th><th>Variant</th><th>Original FIFO batch</th><th>Movement</th><th>Qty</th><th>Landed unit cost</th></tr></thead><tbody>${(()=>{const a=[];(state.sales||[]).forEach(x=>{const p=productById(x.productId),v=variantBySku(p,x.variantSku);(x.batches||[]).forEach(b=>a.push({date:x.date,ref:x.transactionId||x.id,p:p?.name||'Unknown',v:v?`${v.color} · ${v.size}`:x.variantSku,batch:b.ref||'Unbatched',type:'Sold from batch',qty:-b.qty,cost:b.cost||0}))});(state.refunds||[]).forEach(r=>{if(!r.restock)return;const t=tOf(r.txnId);(r.lines||[]).forEach(x=>{const l=t?.lines?.[x.n],p=l&&productById(l.productId),v=l&&variantBySku(p,l.variantSku);(l?.batches||[]).forEach(b=>a.push({date:r.date,ref:r.id,p:p?.name||'Unknown',v:v?`${v.color} · ${v.size}`:l?.variantSku,batch:b.ref||'Original batch',type:'Returned to original batch',qty:x.qty,cost:b.cost||0}))})});return a.sort((x,y)=>(y.date||'').localeCompare(x.date||'')).slice(0,150).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.ref)}</td><td>${esc(x.p)}</td><td>${esc(x.v)}</td><td>${esc(x.batch)}</td><td>${esc(x.type)}</td><td>${x.qty>0?'+':''}${x.qty}</td><td>${money(x.cost)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No batch allocations recorded.</td></tr>'})()}</tbody></table></div></div></details>
<details class="inventory-report-group"><summary><span class="inventory-report-title">Stocktake and adjustment audit</span><span class="inventory-report-description">Physical counts, variances, reasons and recorded responsibility.</span><span class="inventory-report-chevron" aria-hidden="true">⌄</span></summary><div class="inventory-report-content"><div class="table-wrap"><table><thead><tr><th>Stocktake</th><th>Date</th><th>Product</th><th>Variant</th><th>System before</th><th>Counted</th><th>Difference</th><th>Value impact</th><th>Reason</th><th>Responsible user</th></tr></thead><tbody>${(state.stocktakes||[]).flatMap(st=>(st.auditLines||[]).map(x=>{const p=productById(x.productId),v=variantBySku(p,x.sku);return `<tr><td>${esc(st.id)}</td><td>${fmtDate(x.date||st.posted||st.date)}</td><td>${esc(p?.name||'Unknown')}</td><td>${esc(v?`${v.color} · ${v.size}`:x.sku)}</td><td>${x.previous}</td><td>${x.counted}</td><td>${x.difference>0?'+':''}${x.difference}</td><td>${money(x.value)}</td><td>${esc(x.reason)}</td><td>${esc(x.user||'—')}</td></tr>`})).join('')||'<tr><td colspan="10" class="empty">No posted stocktake adjustments recorded yet.</td></tr>'}</tbody></table></div></div></details>
<p class="muted" style="font-size:11px;margin-top:8px">This audit view reconstructs movements from saved receipts, sales, returns and adjustments. Historical user identity and detailed batch movement references are only available where the transaction stored them. Potential gross profit is before operating expenses and assumes all current stock sells at the listed retail price.</p>`}
function printInventoryAudit(mode){pdfInventoryRun(mode||'print')}
function downloadInventoryAudit(){pdfInventoryRun('download')}
function exportInventoryAudit(){const rows=[['Date','Reference','Product','Variant','Movement','Quantity','Batch/source','Unit cost MWK','Responsible user'],...inventoryMovementRows().map(x=>[x.date,x.ref,x.product,x.variant,x.type,x.qty,x.batch,x.cost,x.user])];const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='shop360-inventory-movement-report.csv';a.click();URL.revokeObjectURL(a.href);toast('Inventory movement report exported.')}
