 if(d.period==='custom'){if(!d.customDue||d.customDue<=todayKey()){toast('Choose a completion date after today.');return}due=d.customDue}
 else{const dt=new Date();dt.setDate(dt.getDate()+Math.max(1,+d.period||30));due=dayKey(dt)}
 for(const i of posCart){const p=productById(i.productId),v=variantBySku(p,i.sku);if(!p||!v||Math.min(v.shop,sellable(p,v))<i.qty){toast(`Stock changed for ${p?.name||'an item'}. Review the POS cart.`);return}}
