function showExchangeRefundChoice(id,draft){showModal('Settle exchange balance',`<div class="form-note"><b>Customer is owed: ${money(Math.abs(draft.difference))}</b><br>The replacement item is cheaper than the returned item(s). Choose what should happen to the remaining balance before completing the exchange.</div><form onsubmit="settleExchangeRefund(event,'${id}')"><div class="field"><label>HOW SHOULD THE DIFFERENCE BE SETTLED?</label><select name="handling" required><option value="" selected disabled>Choose refund or Store Credit</option><option value="refund">Refund the customer</option><option value="credit">Add the amount to customer Store Credit</option></select></div><div class="field"><label>REFUND PAYMENT METHOD (ONLY IF REFUNDING)</label><select name="method"><option>Cash</option><option>Bank Transfer</option><option>Airtel Money</option><option>TNM Mpamba</option><option>POS / Card</option></select></div><div class="form-note">The exchange will remain incomplete until you confirm this choice. Cash refunds are checked against the selected account balance.</div><div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancel exchange</button><button class="btn primary">Confirm settlement & complete exchange</button></div></form>`)}
function settleExchangeRefund(e,id){e.preventDefault();const pending=window._pendingExchange,d=formData(e),t=tOf(id);if(!pending||pending.id!==id||!t){toast('This exchange has expired. Please start it again.');return}if(!['refund','credit'].includes(d.handling)){toast('Choose whether to refund the customer or issue Store Credit.');return}if(d.handling==='refund'&&Math.abs(pending.draft.difference)>balanceAt(cashAll(),d.method,todayKey())){toast(`Insufficient balance in ${d.method} to refund ${money(Math.abs(pending.draft.difference))}.`);return}if(!exchangeEligibility(t).allowed){window._pendingExchange=null;toast('This receipt is outside the seven-day exchange period.');closeModal();return}completeExchange(id,pending.draft,{kind:'refund',handling:d.handling,method:d.method});}
function completeExchange(id,draft,settlement){const t=tOf(id);if(!t||!exchangeEligibility(t).allowed){window._pendingExchange=null;toast('This receipt is no longer eligible for exchange.');return}const ret=draft.ret;for(const x of ret){const l=t.lines[x.n];if(!l||x.qty<1||x.qty>l.qty-(t.refQty[x.n]||0)){toast('The returnable quantity has changed. Reopen the exchange and review the items.');return}}const rp=productById(draft.repProductId),rv=variantBySku(rp,draft.repSku),rq=draft.rq;if(!rp||!rv||!Number.isFinite(rq)||rq<1||( +rv.shop||0)<rq||sellable(rp,rv)<rq){toast('Replacement stock has changed. Reopen the exchange and review availability.');return}const returnValue=ret.reduce((a,x)=>a+x.amount,0),balanceCleared=Math.min(returnValue,t.balance||0),creditValue=returnValue-balanceCleared,replacementValue=rq*(+rp.price||0),difference=replacementValue-creditValue;if(returnValue!==draft.returnValue||creditValue!==draft.creditValue||replacementValue!==draft.replacementValue||difference!==draft.difference){toast('The sale or replacement price changed while settling. Please reopen the exchange and review the new difference.');window._pendingExchange=null;return}let storeCreditUsed=0,cashDue=0,method='Exchange',tendered=0,change=0,differenceHandling='none';if(difference>0){if(settlement.kind!=='topup'){toast('The exchange top-up has not been settled.');return}storeCreditUsed=settlement.storeCreditUsed||0;cashDue=settlement.cashDue||0;method=settlement.method||'Customer store credit';tendered=settlement.tendered||0;change=settlement.change||0;if(storeCreditUsed>customerStoreCreditAvailable(t.customer)||storeCreditUsed+cashDue!==difference){toast('The top-up settlement no longer matches the amount due. Reopen the exchange.');return}if(cashDue>0&&method==='Customer store credit'){toast('Select an actual payment method for the remaining amount.');return}if(storeCreditUsed>0&&!consumeCustomerStoreCredit(t.customer,storeCreditUsed,'Exchange top-up '+id)){toast('Store Credit changed. Reopen the exchange and try again.');return}}else if(difference<0){if(settlement.kind!=='refund'||!['refund','credit'].includes(settlement.handling)){toast('Choose how to settle the remaining balance.');return}differenceHandling=settlement.handling;method=settlement.method||'Customer store credit';if(differenceHandling==='refund'&&Math.abs(difference)>balanceAt(cashAll(),method,todayKey())){toast(`Insufficient balance in ${method} to refund ${money(Math.abs(difference))}.`);return}}const restock=draft.restock;let restoredCost=0;if(restock)ret.forEach(x=>{const l=t.lines[x.n],p=productById(l.productId),v=variantBySku(p,l.variantSku);if(v)restoredCost+=restoreSaleStock(p,v,x.qty,l.batches,l.location,'Exchange '+id,t.refQty[x.n]||0,l.unitCost??p.cost)});const refundAmount=difference<0?Math.abs(difference):0,rf={id:'RF-'+(state.refunds.length+1),txnId:id,date:todayKey(),time:nowTime(),lines:ret,amount:returnValue,cashOut:difference<0&&differenceHandling==='refund'?refundAmount:0,creditIssued:difference<0&&differenceHandling==='credit'?refundAmount:0,method:difference<0&&differenceHandling==='refund'?method:'Customer store credit',reason:'Exchange · '+draft.reason,restock,profitAdj:-returnValue+restoredCost,exchange:true};state.refunds.push(rf);if(rf.creditIssued>0){state.customerCredits=state.customerCredits||[];state.customerCredits.unshift({id:'CR-'+String(state.customerCredits.length+1).padStart(3,'0'),customer:t.customer||'Walk-in customer',amount:rf.creditIssued,used:0,date:todayKey(),ref:rf.id+' · exchange balance',status:'Available'});}const take=takeFifo(rp,rv,rq);rv.shop-=rq;const saleId=nextSaleId(),offset=Math.min(creditValue,replacementValue),cashReceived=Math.max(0,replacementValue-storeCreditUsed),paymentMethod=cashDue>0?method:storeCreditUsed>0?'Customer store credit':'Exchange';state.sales.unshift({id:saleId,transactionId:saleId,productId:rp.id,variantSku:rv.sku,channel:'In-store',location:'Shop',qty:rq,unitPrice:rp.price,unitCost:take.unit,batches:take.src,total:replacementValue,date:todayKey(),time:nowTime(),status:'Completed',paymentMethod,depositMethod:cashDue>0?method:'',customer:t.customer,discount:0,transactionTotal:replacementValue,tendered,change,paid:replacementValue,balance:0,cashReceived,storeCreditUsed,exchangeOffset:offset,exchangeReplacement:true});state.exchanges=state.exchanges||[];const ex={id:'EX-'+String(state.exchanges.length+1).padStart(3,'0'),originalSale:id,replacementSale:saleId,date:todayKey(),customer:t.customer,returned:ret.map(x=>{const l=t.lines[x.n],p=productById(l.productId),v=variantBySku(p,l.variantSku);return{productId:l.productId,sku:l.variantSku,name:p?.name||'Item',variant:v?`${v.color} · ${v.size}`:l.variantSku,qty:x.qty,value:x.amount,batches:l.batches||[]}}),replacement:{productId:rp.id,sku:rv.sku,name:rp.name,variant:`${rv.color} · ${rv.size}`,qty:rq,value:replacementValue,batches:take.src},returnValue,balanceCleared,creditValue,replacementValue,difference,method,differenceHandling,storeCreditUsed,cashReceived:cashDue,cashTendered:tendered,change,refundId:rf.id};state.exchanges.unshift(ex);activity('Exchange processed',ex.id,'Shop',`${id} → ${saleId} · difference ${money(Math.abs(difference))}`);window._pendingExchange=null;persist();renderAll();showExchange(ex.id)}
function exchangeHTML(x){const settlement=x.difference>0?`<tr><td>Additional amount due</td><td class="r">${money(x.difference)}</td></tr>${x.storeCreditUsed?`<tr><td>Store Credit applied</td><td class="r">${money(x.storeCreditUsed)}</td></tr>`:''}${x.cashReceived?`<tr><td>Additional payment received (${esc(x.method)})</td><td class="r">${money(x.cashReceived)}</td></tr>`:''}${x.change?`<tr><td>Change returned</td><td class="r">${money(x.change)}</td></tr>`:''}`:x.difference<0?`<tr><td>${x.differenceHandling==='credit'?'Store Credit issued':'Refund paid ('+esc(x.method)+')'}</td><td class="r">${money(Math.abs(x.difference))}</td></tr>`:`<tr><td>Settlement</td><td class="r">No price difference</td></tr>`;return `<div class="receipt"><div class="c">${logoImg(true)}<b>${esc(SHOP.name)}</b><br>EXCHANGE SLIP</div><hr><table><tr><td>Exchange</td><td class="r">${esc(x.id)}</td></tr><tr><td>Original sale</td><td class="r">${esc(x.originalSale)}</td></tr><tr><td>Replacement sale</td><td class="r">${esc(x.replacementSale)}</td></tr><tr><td>Date</td><td class="r">${fmtDate(x.date)}</td></tr><tr><td>Customer</td><td class="r">${esc(x.customer||'Walk-in')}</td></tr><tr><td>Reason</td><td class="r">${esc(x.reason)}</td></tr></table><hr><b>Returned</b><table>${x.returned.map(r=>`<tr><td>${esc(r.name)} · ${esc(r.variant)} × ${r.qty}</td><td class="r">${money(r.value)}</td></tr>`).join('')}</table><hr><b>Replacement</b><table><tr><td>${esc(x.replacement.name)} · ${esc(x.replacement.variant)} × ${x.replacement.qty}</td><td class="r">${money(x.replacement.value)}</td></tr></table><hr><table><tr><td>Returned value</td><td class="r">${money(x.returnValue)}</td></tr><tr><td>Replacement value</td><td class="r">${money(x.replacementValue)}</td></tr>${settlement}</table><hr><div class="c">${esc(SHOP.footer)}</div></div>`}
