const SIZEGROUPS={shoe:[['Toddlers',rg(16,26)],['Kids',rg(27,34)],['Adults',rg(35,46)]],sml:[['Kids',['Kids S','Kids M','Kids L','Kids XL']],['Adults',['S','M','L','XL']]]};
const szCell=z=>`<label class="sz"><span>${z}</span><input type="number" min="0" data-size="${z}" placeholder="0"></label>`;
const gridHTML=c=>{const g=c.sizes!=='custom'&&SIZEGROUPS[c.sizes];if(!g)return (c.sizes==='custom'?(c.custom||[]):SIZESETS[c.sizes]).map(szCell).join('');const def=g.length-1;return `<div class="sz-tabs">${g.map(([n,a],i)=>`<button type="button" class="sz-tab${i===def?' on':''}" data-i="${i}" onclick="szTab(this)">${n}${typeof a[0]==='number'?' <span>'+a[0]+'–'+a[a.length-1]+'</span>':''} <i></i></button>`).join('')}</div>${g.map(([n,a],i)=>`<div class="sz-row" data-p="${i}" style="${i===def?'':'display:none'}">${a.map(szCell).join('')}</div>`).join('')}`};
function szTab(b){const box=b.closest('.size-grid');box.querySelectorAll('.sz-tab').forEach(x=>x.classList.toggle('on',x===b));box.querySelectorAll('.sz-row').forEach(r=>r.style.display=r.dataset.p===b.dataset.i?'':'none')}
function szRefresh(root){(root||document).querySelectorAll('.size-grid').forEach(box=>box.querySelectorAll('.sz-tab').forEach(t=>{const p=box.querySelector('.sz-row[data-p="'+t.dataset.i+'"]');const n=p?[...p.querySelectorAll('[data-size]')].reduce((a,i)=>a+(+i.value||0),0):0;t.querySelector('i').textContent=n?'· '+n:''}))}
document.addEventListener('input',e=>{if(e.target.dataset&&e.target.dataset.size!==undefined)szRefresh(e.target.closest('.size-grid')?.parentNode)});
const modelOf=()=>catOf(ai.cat)?.models.find(m=>m.name===ai.model);
function addItemHTML(mode,oid){const ord=mode==='order',o=ord?state.orders.find(x=>x.id===oid):null;
return `<form id="recordForm" ${ord?'oninput="aiProj()" ':''}onsubmit="${ord?'saveOrderItem(event)':'saveProduct(event)'}"><div id="aiChips"></div>${ord?'<div id="aiNote" class="form-note" style="margin-top:8px"></div>':'<div class="form-note" style="margin-top:8px">Use this for stock already in the shop. New deliveries should come in through Stock orders.</div>'}<div class="form-grid" style="margin-top:8px"><div class="field"><label>SELLING PRICE (MWK)</label><input name="price" type="number" min="1" required></div><div class="field"><label>${ord?`COST PER PAIR (${curLabel(o.cur)})`:'UNIT COST (MWK)'}</label><input name="cost" type="number" step="any" min="0" required></div></div>${FEATURES.expiry?'<div class="form-note" style="margin-top:10px"><label style="display:flex;gap:8px;align-items:center;font-weight:700"><input type="checkbox" name="expiryTracked" onchange="aiExpiry()"> Track expiry for this item</label><div class="muted" style="font-size:11px;margin-top:3px">Enable this for medicines, food and other perishable products. Leave it off for shoes, clothing and other non-expiring goods.</div></div><div class="form-note" id="aiExpNote" style="display:none;margin-top:6px">Expiry dates will be entered when the goods are physically received and inspected.</div>':''}<div id="aiColors"></div><button type="button" class="btn secondary" onclick="aiAddColor()">＋ Add colour</button>${ord?'<div id="aiProj" class="form-note" style="margin-top:10px"></div>':''}<div class="form-actions"><button type="button" class="btn secondary" onclick="${ord?`showOrder('${oid}')`:'closeModal()'}">Cancel</button><button class="btn primary">${ord?'Add to order':'Save product'}</button></div></form>`}
function aiInit(mode,oid){ai.mode=mode==='order'?'order':'product';ai.oid=ai.mode==='order'?oid:'';aiOpen='';aiQ='';ai.cat=state.categories[0]?.name||'';ai.model=ai.sub=ai.brand='';aiRender();aiAddColor();const f=document.getElementById('recordForm');if(f&&f.elements.expiryTracked)f.elements.expiryTracked.checked=false;aiExpiry()}
let aiOpen='',aiQ='';
function aiRender(){const c=catOf(ai.cat),m=modelOf();
const cb=(k,label,val,hint)=>`<div class="ai-row"><label>${label}</label><div class="cbx"><button type="button" class="cbx-btn" onclick="aiToggle('${k}')"><span>${esc(val||hint)}</span><span>▾</span></button>${aiOpen===k?`<div class="cbx-panel"><input id="aiQ" placeholder="Search, or type a new name" oninput="aiFilter(this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault();aiEnter()}"><div id="aiList"></div></div>`:''}</div></div>`;
document.getElementById('aiChips').innerHTML=cb('cat','CATEGORY',ai.cat,'Select category')+(c?`<div class="ai-row"><label>SIZES FOR THIS CATEGORY</label>${Object.entries(SIZELBL).map(([k,v])=>`<span class="chip ${c.sizes===k?'on':''}" onclick="aiSizes('${k}')">${v}${k==='custom'&&c.sizes==='custom'?': '+esc((c.custom||[]).join(', ')):''}</span>`).join('')}</div>`:'')+(c?cb('model','MODEL',ai.model,'Select or add a model'):'')+(m?cb('sub','SUB-CATEGORY (OPTIONAL)',ai.sub,'e.g. Jordan 4'):'')+cb('brand','BRAND',ai.brand,'Select or add a brand');
if(aiOpen){const q=document.getElementById('aiQ');q.value=aiQ;q.focus();aiList()}}
const aiItems=k=>k==='cat'?state.categories.map(x=>x.name):k==='model'?catOf(ai.cat).models.map(x=>x.name):k==='sub'?modelOf().subs:state.brands;
function aiList(){const k=aiOpen,q=aiQ.trim().toLowerCase(),items=aiItems(k);let h=items.map((x,i)=>[x,i]).filter(([x])=>x.toLowerCase().includes(q)).map(([x,i])=>`<div class="cbx-opt ${x===ai[k]?'on':''}" onclick="aiPick('${k}',${i})"><span>${esc(x)}</span><b onclick="event.stopPropagation();aiDel('${k}',${i})">×</b></div>`).join('');
if(q&&!items.some(x=>x.toLowerCase()===q))h+=`<div class="cbx-add" onclick="aiAdd('${k}',aiQ)">＋ Add "${esc(aiQ.trim())}"</div>`;document.getElementById('aiList').innerHTML=h||'<div class="muted" style="padding:8px">Nothing yet. Type a name to add it.</div>'}
function aiToggle(k){aiOpen=aiOpen===k?'':k;aiQ='';aiRender()}
function aiFilter(v){aiQ=v;aiList()}
function aiEnter(){const q=aiQ.trim();if(!q)return;const i=aiItems(aiOpen).findIndex(x=>x.toLowerCase()===q.toLowerCase());i>=0?aiPick(aiOpen,i):aiAdd(aiOpen,q)}
document.addEventListener('click',e=>{if(aiOpen&&!e.target.closest('.cbx')&&document.getElementById('aiChips')){aiOpen='';aiQ='';aiRender()}});
function aiGrids(){const c=catOf(ai.cat);document.querySelectorAll('#aiColors .size-grid').forEach(g=>g.innerHTML=gridHTML(c));document.querySelectorAll('#aiColors .unit').forEach(u=>u.textContent=c.unit)}
function aiSizes(k){const c=catOf(ai.cat);if(k==='custom'){const t=prompt('Type the sizes separated by commas, e.g. S, M, L or 38-40, 41-43',(c.custom||[]).join(', '));if(t===null)return;const a=t.split(',').map(x=>x.trim()).filter(Boolean);if(!a.length)return;c.custom=a}c.sizes=k;persist();aiRender();aiGrids()}
function aiPick(k,i){aiOpen='';aiQ='';const c=catOf(ai.cat);if(k==='cat'){ai.cat=state.categories[i].name;ai.model=ai.sub='';aiRender();aiGrids();const f=document.getElementById('recordForm');if(f&&f.elements.expiryTracked)f.elements.expiryTracked.checked=false;aiExpiry();return}
if(k==='model'){const n=c.models[i].name;ai.model=ai.model===n?'':n;ai.sub='';const p=state.products.find(x=>x.category===ai.cat&&x.model===ai.model&&(x.sub||'')==='');const f=document.getElementById('recordForm');if(f&&f.elements.expiryTracked)f.elements.expiryTracked.checked=p&&p.expiryTracked!==undefined?!!p.expiryTracked:!!c.expiry;aiExpiry()}else if(k==='sub'){const n=modelOf().subs[i];ai.sub=ai.sub===n?'':n;const p=state.products.find(x=>x.category===ai.cat&&x.model===ai.model&&(x.sub||'')===(ai.sub||''));const f=document.getElementById('recordForm');if(f&&f.elements.expiryTracked)f.elements.expiryTracked.checked=p&&p.expiryTracked!==undefined?!!p.expiryTracked:!!c.expiry;aiExpiry()}else{const n=state.brands[i];ai.brand=ai.brand===n?'':n}aiRender()}
function aiAdd(k,n){n=(n||'').trim();if(!n)return;aiOpen='';aiQ='';const same=a=>a.find(x=>String(x.name??x).toLowerCase()===n.toLowerCase());
if(k==='cat'){const f=same(state.categories)||(state.categories.push({name:n,sizes:'shoe',unit:'pairs',models:[]}),state.categories.at(-1));ai.cat=f.name;ai.model=ai.sub='';persist();aiRender();aiGrids();return}
if(k==='model'){const c=catOf(ai.cat),f=same(c.models)||(c.models.push({name:n,subs:[]}),c.models.at(-1));ai.model=f.name;ai.sub=''}
if(k==='sub'){const m=modelOf(),f=same(m.subs)||(m.subs.push(n),n);ai.sub=f.name??f}
if(k==='brand'){const f=same(state.brands)||(state.brands.push(n),n);ai.brand=f}
persist();aiRender()}
function aiDel(k,i){const c=catOf(ai.cat),P=state.products;let n=0,name='';
if(k==='cat'){name=state.categories[i].name;n=P.filter(p=>p.category===name).length}else if(k==='model'){name=c.models[i].name;n=P.filter(p=>p.category===c.name&&p.model===name).length}else if(k==='sub'){name=modelOf().subs[i];n=P.filter(p=>p.category===c.name&&p.sub===name).length}else{name=state.brands[i];n=P.filter(p=>p.brand===name).length}
if(n){toast(`${n} product(s) use "${name}", so it can't be removed.`);return}
if(k==='cat'){state.categories.splice(i,1);if(ai.cat===name){ai.cat=state.categories[0]?.name||'';ai.model=ai.sub=''}aiRender();aiGrids()}else{if(k==='model'){c.models.splice(i,1);if(ai.model===name)ai.model=ai.sub=''}else if(k==='sub'){modelOf().subs.splice(i,1);if(ai.sub===name)ai.sub=''}else{state.brands.splice(i,1);if(ai.brand===name)ai.brand=''}aiRender()}persist()}
function aiAddColor(){const c=catOf(ai.cat),first=document.querySelector('#aiColors .color-block');document.getElementById('aiColors').insertAdjacentHTML('beforeend',`<div class="color-block"><div class="cb-head"><input class="ai-color" placeholder="Colour, e.g. Black" required>${first?'<button type="button" class="tiny-btn" onclick="aiCopy(this)">Copy sizes from first colour</button><button type="button" class="tiny-btn" onclick="this.closest(\'.color-block\').remove();aiProj()">Remove</button>':''}</div><div class="muted" style="font-size:11px;margin-top:8px">Number of <span class="unit">${c.unit}</span> ${ai.mode==='order'?'ordered':'in stock'} in each size</div><div class="size-grid">${gridHTML(c)}</div></div>`)}
function aiCopy(b){aiCopy2(b);szRefresh();aiProj()}
function aiCopy2(b){const src=document.querySelector('#aiColors .color-block').querySelectorAll('[data-size]'),dst=b.closest('.color-block').querySelectorAll('[data-size]');src.forEach((i,n)=>dst[n].value=i.value)}
aiRender=(f=>function(){f();aiNote();aiProj();aiExpiry()})(aiRender);
function adjExpiry(){const f=document.getElementById('recordForm'),sel=f&&f.querySelector('[name=productId]');if(!sel)return;const p=productById(+sel.value),x=!!(p&&expiryManaged(p));['adjExp','adjLot'].forEach(id=>{const e=document.getElementById(id);if(e){e.style.display=x?'':'none';if(id==='adjExp'){const inp=e.querySelector('input');if(inp)inp.required=x}if(!x)e.querySelectorAll('input').forEach(i=>i.value='')}});const r=f.querySelector('[name=reason]');[...r.options].forEach(o=>{if(o.text==='Expired'){o.hidden=!x;o.disabled=!x}});if(r.selectedOptions[0]?.disabled)r.selectedIndex=0}
function aiExpiry(){const f=document.getElementById('recordForm'),t=f&&f.querySelector('[name=expiryTracked]'),w=document.getElementById('aiExpNote');if(!t||!w)return;w.style.display=t.checked?'':'none'}
function aiNote(){const el=document.getElementById('aiNote');if(!el||ai.mode!=='order')return;const p=ai.model&&state.products.find(x=>x.category===ai.cat&&x.model===ai.model&&(x.sub||'')===(ai.sub||''));el.innerHTML=p?`✓ Already in Inventory as “${esc(p.name)}” (${totalPairs(p)} pairs in stock). Receiving this order will add to it.`:ai.model?'New item: it will be created in Inventory when this order is received.':'Pick a category and model, then add colours and the pairs ordered in each size.'}
function aiProj(){const el=document.getElementById('aiProj'),f=document.getElementById('recordForm'),o=state.orders.find(x=>x.id===ai.oid);if(!el||!f||!o||ai.mode!=='order')return;let q=0;document.querySelectorAll('#aiColors [data-size]').forEach(i=>q+=Math.round(+i.value||0));const cost=(+f.elements.cost.value||0)*o.rate*q,rev=(+f.elements.price.value||0)*q;el.innerHTML=q?`This item: <b>${q}</b> pairs · cost ${money(cost)} (before shared extra costs) · revenue if all sold ${money(rev)} · profit ${money(rev-cost)}${rev?' ('+pc((rev-cost)/rev)+')':''}`:'Enter the pairs ordered in each size to see the projection.'}
let aiEdit=null;
function openOrderItem(id){aiEdit=null;showModal('Add item · '+id,addItemHTML('order',id));aiInit('order',id)}
function saveOrderItem(e){e.preventDefault();const d=formData(e),c=catOf(ai.cat),o=state.orders.find(x=>x.id===ai.oid);if(!o||!c||!ai.model){toast('Choose or add a category and a model first.');return}
const variants=[];document.querySelectorAll('#aiColors .color-block').forEach(b=>{const color=b.querySelector('.ai-color').value.trim();if(!color)return;b.querySelectorAll('[data-size]').forEach(i=>{const q=Math.round(+i.value||0);if(q>0){const z=i.dataset.size;variants.push({color,size:isNaN(z)?z:+z,qty:q})}})});
if(!variants.length){toast('Add a colour and the pairs ordered in at least one size.');return}
if(new Set(variants.map(v=>v.color.toLowerCase()+'|'+v.size)).size<variants.length){toast('Two colours look the same. Use different colour names.');return}
saveLine(o,{category:c.name,model:ai.model,sub:ai.sub,brand:ai.brand||'Unbranded',qty:variants.reduce((n,v)=>n+v.qty,0),unitCost:+d.cost,sell:+d.price,variants,expiryTracked:d.expiryTracked==='on'});persist();renderAll();showOrder(o.id);const pw=priceWarn();toast('Order item saved.'+pw);if(pw){clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>document.getElementById('toast').classList.remove('show'),9000)}}

function planGap(o){const g=[];(o.lines||[]).forEach(l=>{const p=state.products.find(x=>x.category===l.category&&x.model===l.model&&(x.sub||'')===(l.sub||''));if(p&&(l.variants||[]).some(v=>v.recv>0)&&Math.round(p.price)!==Math.round(l.sell))g.push(p.name+' '+money(p.price)+' → '+money(l.sell))});return g.join(' · ')}
function fixPlanPrices(id){const o=state.orders.find(x=>x.id===id);if(!o)return;const g=planGap(o);if(!g||!confirm('Change Inventory prices to the planned prices?\n\n'+g.split(' · ').join('\n')+'\n\nThis reprices all pairs of these models in stock.'))return;
o.lines.forEach(l=>{const p=state.products.find(x=>x.category===l.category&&x.model===l.model&&(x.sub||'')===(l.sub||''));if(p&&(l.variants||[]).some(v=>v.recv>0)&&Math.round(p.price)!==Math.round(l.sell)){activity('Price updated',p.name,'Shop',money(p.price)+' → '+money(l.sell)+' ('+pctTxt(p.price,l.sell)+') · '+id);p.price=Math.round(l.sell)}});persist();renderAll();showOrder(id);toast('Inventory prices updated to plan.')}
const pctTxt=(a,b)=>a?((b>=a?'+':'−')+Math.round(Math.abs(b-a)/a*100)+'%'):'';
function priceNote(o){if(!['Draft','Ordered','Part-received'].includes(o.status))return '';const g=(o.lines||[]).map(l=>{const p=state.products.find(x=>x.category===l.category&&x.model===l.model&&(x.sub||'')===(l.sub||''));return p&&Math.round(p.price)!==Math.round(l.sell)&&(l.variants||[]).some(v=>v.qty-(v.recv||0)>0)?`<div><b>${esc(p.name)}</b>: Inventory price ${money(p.price)}, planned ${money(l.sell)} (${pctTxt(p.price,l.sell)}).</div>`:''}).join('');return g?`<div class="form-note" style="margin-top:12px;border:1px solid #e0b34a;background:#fff8e6"><b>⚠ Price check</b>${g}<div class="muted" style="font-size:12px;margin-top:4px">When you receive the stock you can update the Inventory price or keep it.</div></div>`:''}
function priceWarn(){const nl=window._nl;if(!nl)return '';const p=state.products.find(x=>x.category===nl.category&&x.model===nl.model&&(x.sub||'')===(nl.sub||''));return p&&Math.round(p.price)!==Math.round(nl.sell)?` Note: ${p.name} sells at ${money(p.price)} in Inventory but this order plans ${money(nl.sell)} (${pctTxt(p.price,nl.sell)}). You can update it or keep it when you receive.`:''}
function saveLine(o,nl){window._nl=nl;if(aiEdit!=null&&o.lines[aiEdit]){const old=o.lines[aiEdit],rv={};(old.variants||[]).forEach(v=>{if(v.recv)rv[String(v.color).toLowerCase()+'|'+v.size]=v.recv});nl.variants.forEach(v=>{const r=rv[v.color.toLowerCase()+'|'+v.size];if(r)v.recv=r});o.lines[aiEdit]=nl;aiEdit=null;window._lineEdited=true}else o.lines.push(nl)}
function editOrdLine(id,i){const o=state.orders.find(x=>x.id===id),l=o&&o.lines[i];if(!l)return;
showModal('Edit item · '+id,addItemHTML('order',id));aiInit('order',id);aiEdit=i;
ai.cat=l.category;ai.model=l.model;ai.sub=l.sub||'';ai.brand=l.brand==='Unbranded'?'':(l.brand||'');aiRender();aiGrids();
const box=document.getElementById('aiColors');box.innerHTML='';const vs=l.variants||[];
[...new Set(vs.map(v=>v.color))].forEach(c=>{aiAddColor();const bl=box.querySelectorAll('.color-block'),b=bl[bl.length-1];b.querySelector('.ai-color').value=c;vs.filter(v=>v.color===c).forEach(v=>{const inp=b.querySelector('[data-size="'+v.size+'"]');if(inp)inp.value=v.qty})});
if(!vs.length)aiAddColor();
const f=document.getElementById('recordForm');f.elements.price.value=l.sell;f.elements.cost.value=l.unitCost;f.elements.expiryTracked.checked=!!(l.expiryTracked||l.expiry);
f.querySelector('.form-actions .btn.primary').textContent='Save changes';aiNote();aiProj();aiExpiry()}

function openMarkOrdered(id){const o=state.orders.find(x=>x.id===id);if(!o||!o.lines.length){toast('Add at least one item first.');return}
const c=oc(o),g={};c.lines.forEach(l=>(g[l.category]=g[l.category]||[]).push(l));
const body=Object.entries(g).map(([cat,ls])=>`<div style="border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-top:8px"><label style="display:flex;gap:8px;font-weight:800"><input type="checkbox" class="mo-cat" checked onchange="this.closest('div').querySelectorAll('.mo-it').forEach(i=>i.checked=this.checked)"> ${esc(cat)} <span class="muted" style="font-weight:500">· ${ls.reduce((n,l)=>n+l.qty,0)} pairs · ${money(ls.reduce((n,l)=>n+l.cost,0))}</span></label>${ls.map(l=>`<label style="display:flex;gap:8px;margin:6px 0 0 24px;font-size:12px"><input type="checkbox" class="mo-it" name="i_${l.i}" checked onchange="moSync(this)"> ${esc(l.sub||l.model)} · ${l.qty} pairs</label>`).join('')}</div>`).join('');
showModal('Mark as ordered · '+id,`<form onsubmit="saveMarkOrdered(event,'${id}')"><div class="form-note">Tick the categories or items you are ordering from the supplier now. Anything left unticked moves to a new draft order, with its share of the extra costs.</div><div style="margin:8px 0"><button type="button" class="tiny-btn" onclick="moAll(true)">Mark all</button> <button type="button" class="tiny-btn" onclick="moAll(false)">Clear all</button></div>${body}<div class="form-actions"><button type="button" class="btn secondary" onclick="showOrder('${id}')">Back</button><button class="btn primary">Mark selected as ordered</button></div></form>`)}
function moSync(el){const d=el.closest('div');d.querySelector('.mo-cat').checked=[...d.querySelectorAll('.mo-it')].every(i=>i.checked)}
function moAll(v){document.querySelectorAll('.mo-cat,.mo-it').forEach(i=>i.checked=v)}
function saveMarkOrdered(e,id){e.preventDefault();const o=state.orders.find(x=>x.id===id),keep=new Set();o.lines.forEach((l,i)=>{if(document.querySelector('.mo-it[name="i_'+i+'"]')?.checked)keep.add(i)});if(!keep.size){toast('Tick at least one item to order.');return}pendMO={id,keep};if(linkOn()){payDraft=null;openOrderPay(id,'order')}else{const nd=commitMarkOrdered(id,keep);finishOrdered(id,nd)}}
function rcRow(cb){const i=cb.closest('tr').querySelector('[data-rem]');i.value=cb.checked?i.dataset.rem:0;rcSync()}
function rcNum(i){i.closest('tr').querySelector('.rc-v').checked=+i.value>=+i.dataset.rem;rcSync()}
function rcGroup(cb){const d=cb.closest('details');d.querySelectorAll('tr').forEach(tr=>{const i=tr.querySelector('[data-rem]');if(!i)return;i.value=cb.checked?i.dataset.rem:0;tr.querySelector('.rc-v').checked=cb.checked});d.querySelectorAll('.rc-i').forEach(x=>x.checked=cb.checked);rcSync()}
function rcSync(){document.querySelectorAll('.rc-item').forEach(d=>{const r=[...d.querySelectorAll('.rc-v')];d.querySelector('.rc-i').checked=r.length>0&&r.every(x=>x.checked)});document.querySelectorAll('.rc-cat').forEach(d=>{const r=[...d.querySelectorAll('.rc-i')];d.querySelector('.rc-c').checked=r.length>0&&r.every(x=>x.checked)})}
function rcAll(v){document.querySelectorAll('.rc-cat .rc-c').forEach(c=>{c.checked=v;rcGroup(c)})}


function saveLayCustomer(l){state.customers=state.customers||[];const d=l.cust||{};let c=state.customers.find(x=>custKey(x.name)===custKey(l.customer));if(!c){c={id:'C-'+String(state.customers.length+1).padStart(3,'0'),type:d.type||'Individual',name:l.customer,contact:'',phone:l.phone||'',email:d.email||'',address:d.address||'',tin:'',terms:'Pay on purchase',notes:'',created:todayKey()};state.customers.push(c)}else{c.phone=l.phone||c.phone;c.email=d.email||c.email;c.address=d.address||c.address;c.type=d.type||c.type}return c}
function layCust(name){const f=document.getElementById('layForm'),n=document.getElementById('layCustNote'),x=custStats().find(c=>custKey(c.name)===custKey(name));if(!f)return;
if(x&&x.reg){f.elements.customer.value=x.name;f.elements.phone.value=x.phone||'';f.elements.email.value=x.email||'';f.elements.address.value=x.address||'';f.elements.ctype.value=x.type||'Individual';n.textContent='Existing customer. Their saved details were filled in; you can still change them.'}
else n.textContent='New customer. Their profile will be created when this lay-by is saved.'}


const sk=t=>String(t||'').trim().toLowerCase();
function ensureSuppliers(){state.suppliers=state.suppliers||[];(state.orders||[]).forEach(o=>{if(o.supplier&&!state.suppliers.some(x=>sk(x.name)===sk(o.supplier)))state.suppliers.push({id:'S-'+String(state.suppliers.length+1).padStart(3,'0'),name:String(o.supplier).trim(),country:o.country||'',cur:o.cur||'MWK',contact:'',phone:'',email:'',address:'',notes:'',creditBalance:0,creditLedger:[],created:todayKey()})});state.suppliers.forEach(x=>{if(!Number.isFinite(+x.creditBalance))x.creditBalance=0;x.creditLedger=x.creditLedger||[]})}
function lastOrderFor(p){return (state.orders||[]).find(o=>(o.lines||[]).some(l=>l.category===p.category&&l.model===p.model&&(l.sub||'')===(p.sub||'')))}
function supSel(sel){if(!sel||!sel.form)return;const f=sel.form,nw=sel.value==='__new',ni=f.elements.supplierNew;ni.style.display=nw?'':'none';ni.required=nw;if(nw)return;const x=state.suppliers.find(y=>y.name===sel.value);if(!x)return;
const lo=state.orders.find(o=>sk(o.supplier)===sk(x.name));f.elements.country.value=x.country||(lo?lo.country:'')||'';
if(lo){f.elements.cur.value=lo.cur;f.elements.rate.value=lo.cur==='MWK'?'':lo.rate}else if(x.cur)f.elements.cur.value=x.cur}
function supplierCredit(x){return Math.max(0,Math.round(+x.creditBalance||0))}
function supStats(x){const os=(state.orders||[]).filter(o=>sk(o.supplier)===sk(x.name)),active=os.filter(o=>o.status!=='Draft'&&o.status!=='Cancelled'),spent=active.reduce((a,o)=>a+ordDue(o),0),paid=active.reduce((a,o)=>a+ordPaid(o),0),refunds=active.reduce((a,o)=>a+(o.supplierRefunds||[]).reduce((n,r)=>n+(+r.amount||0),0),0);return{os,spent,paid,refunds,credit:supplierCredit(x),owed:Math.max(0,Math.round(spent-paid)),last:os.filter(o=>o.status!=='Draft').map(o=>o.orderedDate||o.date).sort().pop(),open:os.filter(o=>['Draft','Ordered','Part-received'].includes(o.status)).length}}
function renderSuppliers(){const cd=document.getElementById('supCards');if(!cd)return;ensureSuppliers();const q=sk(document.getElementById('supSearch')?.value),all=state.suppliers.map(x=>({x,t:supStats(x)})),L=all.filter(({x})=>!q||sk([x.name,x.country,x.contact,x.phone].join(' ')).includes(q)).sort((a,b)=>b.t.spent-a.t.spent);
cd.innerHTML=stat('Suppliers',state.suppliers.length,'Registered','⚑')+stat('Total purchases',money(all.reduce((a,y)=>a+y.t.spent,0)),'Non-draft order value','💰')+stat('Supplier balances',money(all.reduce((a,y)=>a+y.t.owed,0)),'Outstanding across suppliers','◷')+stat('Supplier credits',money(all.reduce((a,y)=>a+y.t.credit,0)),'Available for future orders','＋');
document.getElementById('supBody').innerHTML=L.map(({x,t})=>`<tr style="cursor:pointer" onclick="showSupplier('${x.id}')"><td><b>${esc(x.name)}</b></td><td>${esc(x.country||'—')} · ${esc(x.cur==='MWK'||!x.cur?'MWK':x.cur)}</td><td>${esc(x.contact||'—')}${x.phone?'<div class="muted">'+esc(x.phone)+'</div>':''}</td><td>${t.os.length}</td><td>${money(t.spent)}</td><td>${t.last?fmtDate(t.last):'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No suppliers found.</td></tr>'}
function showSupplier(id){const x=state.suppliers.find(y=>y.id===id);if(!x)return;const t=supStats(x),it={},hist=[];t.os.filter(o=>o.status!=='Draft').slice().reverse().forEach(o=>(o.lines||[]).forEach(l=>{const k=l.sub||l.model,i=it[k]=it[k]||{q:0};i.q+=l.qty;i.c=l.unitCost;i.cur=o.cur;i.o=o.id}));t.os.forEach(o=>(o.payments||[]).forEach(p=>hist.push({date:p.date,ref:o.id,method:p.method,amount:p.amount})));(x.creditLedger||[]).forEach(a=>hist.push({date:a.date,ref:a.ref||'Supplier credit',method:a.type,amount:a.amount}));hist.sort((a,b)=>String(b.date).localeCompare(String(a.date)));
showModal(x.name,`<div class="muted">${esc([x.country,curLabel(x.cur)].filter(Boolean).join(' · '))}</div><div class="form-note" style="margin:8px 0">${esc(x.contact||'No contact person saved')}${x.phone?' · '+esc(x.phone):''}${x.email?' · '+esc(x.email):''}${x.address?'<br>'+esc(x.address):''}${x.notes?'<br><i>'+esc(x.notes)+'</i>':''}</div><div class="cards">${stat('Orders',t.os.length,'All time','✎')}${stat('Total purchases',money(t.spent),'Non-draft order value','💰')}${stat('Payments recorded',money(t.paid),'Including supplier credit applied','↗')}${stat('Outstanding',money(t.owed),'Order balances','◷')}${stat('Available supplier credit',money(t.credit),'Can be used on a future order','＋')}</div><h4>Order history</h4><div class="table-wrap"><table><thead><tr><th>Ref</th><th>Order date</th><th>Status</th><th>Pairs</th><th>Total cost</th><th>Paid</th><th>Balance</th></tr></thead><tbody>${t.os.map(o=>{const c=oc(o);return `<tr style="cursor:pointer" onclick="showOrder('${o.id}')"><td><b>${o.id}</b></td><td>${fmtDate(o.orderedDate||o.date)}</td><td>${o.status}</td><td>${c.qty}</td><td>${money(ordDue(o))}</td><td>${money(ordPaid(o))}</td><td>${money(Math.max(0,ordDue(o)-ordPaid(o)))}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No orders yet.</td></tr>'}</tbody></table></div><h4>Payment & credit history</h4><div class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th>Type / method</th><th>Amount</th></tr></thead><tbody>${hist.map(a=>`<tr><td>${fmtDate(a.date)}</td><td>${esc(a.ref)}</td><td>${esc(a.method||'Payment')}</td><td>${money(a.amount)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No payments recorded yet.</td></tr>'}</tbody></table></div><h4>Items bought</h4><div class="table-wrap"><table><thead><tr><th>Item</th><th>Pairs ordered</th><th>Last unit cost</th><th>Last order</th></tr></thead><tbody>${Object.entries(it).map(([k,i])=>`<tr><td><b>${esc(k)}</b></td><td>${i.q}</td><td>${curLabel(i.cur)} ${Number(i.c).toLocaleString()}</td><td>${i.o}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nothing yet.</td></tr>'}</tbody></table></div><div class="form-actions"><button class="btn secondary" onclick="closeModal()">Close</button><button class="btn secondary" onclick="openSupplier('${id}')">Edit</button><button class="btn primary" onclick="openOrder('','${esc(x.name).replace(/'/g,'')}')">New stock order</button></div>`)}
function openSupplier(id){const x=id?state.suppliers.find(y=>y.id===id):{};if(!x)return;const v=k=>esc(x[k]||'');showModal(id?'Edit supplier':'Add supplier',`<form onsubmit="saveSupplier(event,'${id||''}')"><div class="form-grid"><div class="field"><label>SUPPLIER NAME</label><input name="name" required value="${v('name')}"></div><div class="field"><label>COUNTRY</label><input name="country" value="${v('country')}"></div><div class="field"><label>CURRENCY</label><select name="cur">${CURS.map(c=>`<option value="${c}"${c===(x.cur||'MWK')?' selected':''}>${curLabel(c)}</option>`).join('')}</select></div><div class="field"><label>CONTACT PERSON</label><input name="contact" value="${v('contact')}"></div><div class="field"><label>PHONE</label><input name="phone" value="${v('phone')}"></div><div class="field"><label>EMAIL</label><input name="email" type="email" value="${v('email')}"></div></div><div class="field"><label>ADDRESS</label><input name="address" value="${v('address')}"></div><div class="field"><label>NOTES</label><input name="notes" value="${v('notes')}"></div><div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button>${id&&!supStats(x).os.length?`<button type="button" class="btn secondary" onclick="delSupplier('${id}')">Delete</button>`:''}<button class="btn primary">Save supplier</button></div></form>`)}
function saveSupplier(e,id){e.preventDefault();const d=formData(e),nm=d.name.trim();if(!nm)return;ensureSuppliers();if(state.suppliers.some(y=>y.id!==id&&sk(y.name)===sk(nm))){toast('A supplier with that name already exists.');return}
const r={name:nm,country:d.country.trim(),cur:d.cur,contact:d.contact.trim(),phone:d.phone.trim(),email:d.email.trim(),address:d.address.trim(),notes:d.notes.trim()};
if(id){const x=state.suppliers.find(y=>y.id===id),old=x.name;Object.assign(x,r);if(old!==nm)state.orders.forEach(o=>{if(sk(o.supplier)===sk(old))o.supplier=nm})}else state.suppliers.push({id:'S-'+String(Math.max(0,...state.suppliers.map(y=>+String(y.id).replace(/\D/g,'')||0))+1).padStart(3,'0'),...r,created:todayKey()});
activity('Supplier '+(id?'updated':'added'),nm,'Shop','');persist();renderAll();closeModal();toast('Supplier saved.')}
function delSupplier(id){const x=state.suppliers.find(y=>y.id===id);if(!x||supStats(x).os.length||!confirm('Delete '+x.name+'?'))return;state.suppliers=state.suppliers.filter(y=>y.id!==id);persist();renderAll();closeModal();toast('Supplier deleted.')}


function rcId(){return 'RC-'+String(Math.max(0,...state.receivings.map(r=>+String(r.id).replace(/\D/g,'')||0))+1).padStart(3,'0')}
/* ---------- Stocktake ---------- */
function stkVars(st){const o=[];state.products.forEach(p=>p.variants.forEach(v=>{const c=st.counts[v.sku];if(c===undefined)return;const sys=(+v.shop||0);if(c!==sys)o.push({p,v,sys,c,diff:c-sys})}));return o}
function stkDiff(c,sys){return c===undefined?'<span class="muted">—</span>':(c===sys?'<span style="color:#1f7a4d">✓ matches</span>':`<b style="color:${c<sys?'#b43c3c':'#1f7a4d'}">${c-sys>0?'+':''}${c-sys}</b>`)}
function openStocktake(){state.stocktakes=state.stocktakes||[];const op=state.stocktakes.find(x=>x.status==='Open'),done=state.stocktakes.filter(x=>x.status==='Posted').slice(0,5);
showModal('Stocktake',`<div class="form-note">Count what is physically on the shelf and type it in. Only the lines you enter are checked, and blank lines are ignored. Differences are shown to you first and become stock adjustments only when you approve them.</div>${op?`<div class="form-note" style="margin-top:8px"><b>${op.id}</b> is in progress: ${op.scope?esc(op.scope):'all categories'}, started ${fmtDate(op.date)}, ${Object.keys(op.counts).length} line(s) counted.</div><div class="form-actions" style="justify-content:flex-start"><button class="btn primary" onclick="stkSheet('${op.id}')">Continue ${op.id}</button><button class="btn secondary" onclick="discardStocktake('${op.id}')">Discard it</button></div>`:''}<div class="field" style="margin-top:10px"><label>START A NEW COUNT FOR</label><select id="stkScope"><option value="">All categories</option>${state.categories.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div>${done.length?`<h4>Previous stocktakes</h4>${done.map(x=>`<div class="muted" style="margin:4px 0"><b>${x.id}</b> · ${fmtDate(x.posted||x.date)} · ${x.scope?esc(x.scope):'All categories'} · ${x.lines||0} counted · ${x.vars||0} difference(s) · ${(x.value||0)>0?'+':''}${money(x.value||0)}</div>`).join('')}`:''}<div class="form-actions"><button class="btn secondary" onclick="closeModal()">Close</button><button class="btn primary" onclick="startStocktake()">Start new count</button></div>`)}
function startStocktake(){const sc=document.getElementById('stkScope').value;state.stocktakes=state.stocktakes||[];if(state.stocktakes.some(x=>x.status==='Open')&&!confirm('A count is already in progress. Start another one?'))return;const id='ST-'+String(Math.max(0,...state.stocktakes.map(x=>+String(x.id).replace(/\D/g,'')||0))+1).padStart(3,'0');state.stocktakes.unshift({id,date:todayKey(),scope:sc,status:'Open',counts:{}});persist();stkSheet(id)}
function discardStocktake(id){if(!confirm('Discard this count? Your stock is not changed.'))return;state.stocktakes=state.stocktakes.filter(x=>x.id!==id);persist();openStocktake()}
function stkSheet(id){const st=state.stocktakes.find(x=>x.id===id);if(!st)return;const by={};state.products.filter(p=>!st.scope||p.category===st.scope).forEach(p=>(by[p.category]=by[p.category]||[]).push(p));
const body=Object.entries(by).map(([cat,ps])=>`<details class="stk-cat" open style="border:1px solid var(--line);border-radius:12px;padding:8px 12px;margin-top:8px"><summary style="cursor:pointer;font-weight:800">${esc(cat)} <span class="muted" style="font-weight:500">· ${ps.length} item(s)</span></summary>${ps.map(p=>`<details class="stk-p" data-name="${esc((p.name+' '+(p.brand||'')+' '+p.category).toLowerCase())}" style="margin:6px 0 0 14px"><summary style="cursor:pointer"><b>${esc(p.name)}</b> <span class="muted">· ${esc(p.brand||'')}</span> <button type="button" class="tiny-btn" onclick="event.preventDefault();stkMatch('${id}',${p.id},true)">All match</button> <button type="button" class="tiny-btn" onclick="event.preventDefault();stkMatch('${id}',${p.id},false)">Clear</button></summary><div class="table-wrap"><table><thead><tr><th>Colour</th><th>Size</th><th>System</th><th>Counted</th><th>Difference</th></tr></thead><tbody>${p.variants.map(v=>{const sys=(+v.shop||0),c=st.counts[v.sku];return `<tr><td>${esc(v.color)}</td><td>${v.size}</td><td>${sys}</td><td><input type="number" min="0" class="stk-in" data-p="${p.id}" data-sku="${esc(v.sku)}" data-sys="${sys}" value="${c===undefined?'':c}" oninput="stkIn(this,'${id}')" onchange="persist()" style="width:70px"></td><td class="stk-d">${stkDiff(c,sys)}</td></tr>`}).join('')}</tbody></table></div></details>`).join('')}</details>`).join('');
showModal('Stocktake · '+id,`<div class="form-note">${st.scope?esc(st.scope):'All categories'} · started ${fmtDate(st.date)}. Open an item, type what you counted, and leave blank anything you have not counted. Progress saves as you go.</div><div style="margin:8px 0;display:flex;gap:8px;flex-wrap:wrap;align-items:center"><input class="search" placeholder="Search item or brand" oninput="stkFilter(this.value)"><button type="button" class="tiny-btn" onclick="document.querySelectorAll('.stk-p').forEach(d=>d.open=true)">Open all items</button><button type="button" class="tiny-btn" onclick="document.querySelectorAll('.stk-p').forEach(d=>d.open=false)">Close all items</button></div><div id="stkSum" class="muted" style="margin:6px 0"></div>${body||'<div class="empty">No products to count.</div>'}<div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal()">Save and close</button><button type="button" class="btn primary" onclick="reviewStocktake('${id}')">Review differences →</button></div>`);stkSum(st)}
function stkSum(st){const e=document.getElementById('stkSum');if(e)e.textContent=Object.keys(st.counts).length+' line(s) counted · '+stkVars(st).length+' difference(s)'}
function stkIn(el,id){const st=state.stocktakes.find(x=>x.id===id);if(!st)return;if(el.value==='')delete st.counts[el.dataset.sku];else st.counts[el.dataset.sku]=Math.max(0,Math.round(+el.value));el.closest('tr').querySelector('.stk-d').innerHTML=stkDiff(st.counts[el.dataset.sku],+el.dataset.sys);stkSum(st)}
function stkMatch(id,pid,fill){document.querySelectorAll('.stk-in[data-p="'+pid+'"]').forEach(i=>{i.value=fill?i.dataset.sys:'';stkIn(i,id)});persist()}
function stkFilter(q){q=String(q||'').toLowerCase();document.querySelectorAll('.stk-p').forEach(d=>d.style.display=!q||d.dataset.name.includes(q)?'':'none')}
function reviewStocktake(id){const st=state.stocktakes.find(x=>x.id===id);if(!st)return;persist();const V=stkVars(st),lost=V.filter(x=>x.diff<0).reduce((a,x)=>a-x.diff*variantAvgCost(x.p,x.v),0),gain=V.filter(x=>x.diff>0).reduce((a,x)=>a+x.diff*variantAvgCost(x.p,x.v),0);
const rows=V.map((x,i)=>{const neg=x.diff<0,op=(neg?['Count correction','Damaged','Lost or stolen',...(FEATURES.expiry?['Expired']:[])]:['Count correction','Found','Customer return']).map(r=>`<option>${r}</option>`).join('');return `<tr><td><b>${esc(x.p.name)}</b></td><td>${esc(x.v.color)} · ${x.v.size}</td><td>${x.sys}</td><td>${x.c}</td><td><b style="color:${neg?'#b43c3c':'#1f7a4d'}">${x.diff>0?'+':''}${x.diff}</b></td><td>${money(Math.abs(x.diff)*x.p.cost)}</td><td><select name="r_${i}">${op}</select></td></tr>`}).join('');
showModal('Review · '+id,`<form onsubmit="postStocktake(event,'${id}')"><div class="form-note">${Object.keys(st.counts).length} line(s) counted. ${V.length?`<b>${V.length}</b> differ from the system. Short by ${money(lost)} at cost, over by ${money(gain)} at cost. Choose a reason for each, then post. Posting changes your stock.`:'Everything you counted matches the system.'}</div>${V.length?`<div class="table-wrap"><table><thead><tr><th>Item</th><th>Colour · size</th><th>System</th><th>Counted</th><th>Difference</th><th>Value at cost</th><th>Reason</th></tr></thead><tbody>${rows}</tbody></table></div>`:''}<div class="form-actions"><button type="button" class="btn secondary" onclick="stkSheet('${id}')">← Back to count</button><button class="btn primary">${V.length?'Post '+V.length+' adjustment(s)':'Finish stocktake'}</button></div></form>`)}
function postStocktake(e,id){e.preventDefault();const d=formData(e),st=state.stocktakes.find(x=>x.id===id);if(!st||st.status!=='Open')return;const V=stkVars(st);let val=0;
st.auditLines=[];V.forEach((x,i)=>{const re=d['r_'+i]||'Count correction',p=x.p,v=x.v,cost=variantAvgCost(p,v),previous=x.sys;ensureBatches(p);if(x.diff>0)addBatch(p,v,x.diff,cost,'Stocktake '+id,todayKey(),{});else{takeFifo(p,v,-x.diff,re==='Expired'?'expired':'sale');v.shop=Math.max(0,v.shop+x.diff)}
val+=x.diff*cost;st.auditLines.push({productId:p.id,sku:v.sku,previous,counted:x.c,difference:x.diff,value:Math.round(x.diff*cost),reason:re,date:todayKey(),user:SHOP.cashier||'Recorded user'});state.receivings.unshift({id:rcId(),productId:p.id,sku:v.sku,supplier:'',location:'Shop',qty:x.diff,cost:Math.round(cost),date:todayKey(),source:'Adjustment',reason:'Stocktake '+id+' · '+re,user:SHOP.cashier||'Recorded user'})});
st.status='Posted';st.posted=todayKey();st.vars=V.length;st.value=Math.round(val);st.lines=Object.keys(st.counts).length;activity('Stocktake posted',id,'Shop',V.length+' difference(s) · '+(val>0?'+':'')+money(Math.round(val)));persist();closeModal();renderAll();toast(V.length?'Stocktake posted. '+V.length+' adjustment(s) added to the stock log.':'Stocktake finished. No differences.')}
/* ---------- Import inventory ---------- */
const IMP_COLS=['Category','Model','Sub-model (optional)','Brand','Colour','Size','Quantity','Cost price (MWK)','Selling price (MWK)',...(FEATURES.expiry?['Expiry date (optional)','Lot (optional)']:[])];
const IMP_EX=[['Sneakers','Jordan','Jordan 4','Nike','Black',42,6,35000,60000,'',''],['Sneakers','Jordan','Jordan 4','Nike','Black',43,6,35000,60000,'',''],['Shirts','Polo','','Unbranded','White','M',10,12000,25000,'','']];
const IMP_HELP=[['How to fill this template'],['One row = one colour and one size of an item.'],['Category must match a category in Shop360, or tick "create missing categories" when importing.'],['Items that already exist (same category, model and sub-model) get the quantity added as a new stock batch.'],['New items need a selling price. Cost price is what you paid per item.'],['Sizes: numbers such as 42, or letters such as M, XL.'],['Delete the three example rows before you upload.']];
const IMPMAP={category:'cat',model:'model',submodel:'sub',submodeloptional:'sub',sub:'sub',brand:'brand',colour:'color',color:'color',size:'size',quantity:'qty',qty:'qty',costprice:'cost',costpricemwk:'cost',cost:'cost',unitcost:'cost',sellingprice:'price',sellingpricemwk:'price',price:'price',expirydate:'expiry',expirydateoptional:'expiry',expiry:'expiry',lot:'lot',lotoptional:'lot'};
let impRows=null,impOpt={create:true,price:false};
function loadXLSX(cb){if(window.XLSX)return cb(window.XLSX);const sc=document.createElement('script');sc.src='https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';sc.onload=()=>cb(window.XLSX||null);sc.onerror=()=>cb(null);document.head.appendChild(sc)}
function toCSV(rows){return rows.map(r=>r.map(c=>/[",\n;]/.test(String(c))?'"'+String(c).replace(/"/g,'""')+'"':c).join(',')).join('\r\n')}
function parseCSV(t){t=String(t).replace(/^\ufeff/,'');const first=t.split(/\r?\n/)[0]||'',dl=first.includes(';')&&!first.includes(',')?';':',',rows=[];let r=[],c='',q=false;
for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch==='"'){if(t[i+1]==='"'){c+='"';i++}else q=false}else c+=ch}else if(ch==='"')q=true;else if(ch===dl){r.push(c);c=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&t[i+1]==='\n')i++;r.push(c);rows.push(r);r=[];c=''}else c+=ch}
if(c!==''||r.length){r.push(c);rows.push(r)}return rows}
function dlFile(name,type,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;document.body.appendChild(a);a.click();a.remove()}
function dlTemplate(kind){if(kind==='csv'){dlFile('Shop360-inventory-template.csv','text/csv','\ufeff'+toCSV([IMP_COLS,...IMP_EX]));return}
loadXLSX(X=>{if(!X){toast('The Excel tools could not load (are you offline?). Downloading the CSV template instead.');dlTemplate('csv');return}const wb=X.utils.book_new();X.utils.book_append_sheet(wb,X.utils.aoa_to_sheet([IMP_COLS,...IMP_EX]),'Inventory');X.utils.book_append_sheet(wb,X.utils.aoa_to_sheet(IMP_HELP),'How to fill');X.writeFile(wb,'Shop360-inventory-template.xlsx')})}
function openImport(){impRows=null;showModal('Import inventory',`<div class="form-note">Fill in the template and upload it. Each row is one colour and size of an item. New items are created, and items that already exist get the quantity added as a new stock batch. You see a preview first, and nothing is saved until you confirm.</div><div style="margin:10px 0;display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="btn secondary" onclick="dlTemplate('xlsx')">⬇ Excel template</button><button type="button" class="btn secondary" onclick="dlTemplate('csv')">⬇ CSV template</button></div><div class="field"><label>UPLOAD YOUR FILE (.xlsx, .xls or .csv)</label><input type="file" accept=".xlsx,.xls,.csv" onchange="impFile(this)"></div><div class="form-note" style="margin-top:8px">Excel files need an internet connection the first time, to load the Excel reader. CSV files work offline.</div><div class="form-actions"><button class="btn secondary" onclick="closeModal()">Close</button></div>`)}
