if(!p){p={id:Math.max(0,...state.products.map(x=>x.id))+1,name:sn||m.name,model:m.name,sub:sn,brand:r.brand||'Unbranded',category:c.name,price:r.price||0,cost:r.cost,emoji:EMOJI[c.name]||'📦',variants:[]};if(!(p.price>0)){const f=pl.ok.find(o=>o.key===r.key&&o.price>0);p.price=f?f.price:0}state.products.push(p);np++}
else if(impOpt.price&&r.price>0&&Math.round(r.price)!==Math.round(p.price)){activity('Price updated',p.name,'Shop',money(p.price)+' → '+money(r.price)+' · import');p.price=Math.round(r.price)}
let v=p.variants.find(x=>L(x.color)===L(r.color)&&String(x.size)===String(r.size));
