(state.payments||[]).filter(p=>p.method!=='Customer store credit'&&!p.storeCreditUsed).forEach(p=>L.push({d:p.date,tm:p.time||'',desc:'Credit payment · sale '+p.txnId,cat:'Credit payments',pm:p.method,tgt:p,in:p.amount,out:0,auto:1,ref:p.id}));
(state.layaways||[]).forEach(l=>{(l.payments||[]).forEach(p=>L.push({d:p.date,tm:p.time||'',desc:'Lay-by '+l.id+' · '+l.customer,cat:'Lay-by payments',pm:p.method,tgt:p,in:p.amount,out:0,auto:1,ref:l.id}));if(l.refund&&!l.refund.cashbookId&&l.refund.amount>0&&((l.refund.cashAmount??l.refund.amount)>0))L.push({d:l.refund.date,tm:'',desc:'Lay-by refund '+l.id+' · '+l.customer,cat:'Refunds',pm:l.refund.method,tgt:l.refund,in:0,out:(l.refund.cashAmount??l.refund.amount),auto:1,ref:l.id});(l.adjustments||[]).filter(a=>a.type==='refund'&&a.amount>0&&(a.cashAmount??a.amount)>0).forEach(a=>L.push({d:a.date,tm:a.time||'',desc:'Lay-by revision refund '+l.id+' · '+l.customer,cat:'Refunds',pm:a.method,tgt:a,in:0,out:(a.cashAmount??a.amount),auto:1,ref:l.id}))});
(state.refunds||[]).forEach(r=>{if(r.cashOut>0)L.push({d:r.date,tm:r.time||'',desc:'Refund '+r.id+' · sale '+r.txnId,cat:'Refunds',pm:r.method,tgt:r,in:0,out:r.cashOut,auto:1,ref:r.id})});
