/* ---------- Order extra costs, payments and Cashbook link ---------- */
const EX_CATS=['Transport','Air ticket','Shipping / freight','Customs duty','Lodging','Clearing agent','Insurance'];
let pendMO=null,payDraft=null;
function exs(o){return Array.isArray(o.extras)?o.extras:((+o.extra||0)>0?[{id:'E0',cat:'Extra costs (not itemised)',amount:+o.extra,spread:'item',date:o.date,legacy:1}]:[])}
function ordExtras(o){if(!Array.isArray(o.extras))o.extras=exs(o).map(e=>({...e}));return o.extras}
function syncX(o){o.extra=ordExtras(o).filter(e=>!e.late).reduce((a,e)=>a+e.amount,0)}
function ordLocked(o){return o.status==='Part-received'||o.status==='Received'}
function linkOn(){return SHOP.linkOrders!==false}
function setLinkOrders(v){SHOP.linkOrders=!!v;persist();toast(v?'Orders are linked to the Cashbook.':'Orders are no longer linked to the Cashbook.')}
function exCats(){return [...EX_CATS,...(state.exCats||[]).filter(c=>!EX_CATS.includes(c)),'Other']}
function ordDue(o){const c=oc(o);return c.cost+c.late}
function ordPaid(o){return (o.payments||[]).reduce((a,p)=>a+(+p.amount||0),0)}
function ordCashPaid(o){return (o.payments||[]).filter(p=>p.method!=='Supplier credit'&&p.method!=='Supplier refund'&&p.method!=='Supplier credit issued').reduce((a,p)=>a+(+p.amount||0),0)}
function ordCreditApplied(o){return (o.payments||[]).filter(p=>p.method==='Supplier credit').reduce((a,p)=>a+(+p.amount||0),0)}
function ordOwed(o){return Math.max(0,Math.round(ordDue(o)-ordPaid(o)))}
function nextCb(){return 'CB-'+String(Math.max(0,...(state.cashbook||[]).map(y=>+String(y.id).replace(/\D/g,'')||0))+1).padStart(3,'0')}
function extrasHTML(o){const L=exs(o),lock=ordLocked(o),inL=L.filter(e=>!e.late).reduce((a,e)=>a+e.amount,0),late=L.filter(e=>e.late).reduce((a,e)=>a+e.amount,0),can=e=>e.late||!lock||o.corr;
return `<h3 style="margin:14px 0 8px;font-size:14px">Extra costs</h3>${L.length?`<div class="table-wrap"><table><thead><tr><th>Category</th><th>Note</th><th>Spread</th><th>Date</th><th>Amount</th><th></th></tr></thead><tbody>${L.map(e=>`<tr${can(e)?` style="cursor:pointer" title="Click to edit" onclick="openExtra('${o.id}','${e.id}')"`:''}><td>${esc(e.cat)}${e.late?' <span class="muted">· after receiving</span>':''}</td><td>${esc(e.note||'—')}</td><td>${e.late?'Record only':(e.spread==='value'?'By value':'Per item')}</td><td>${fmtDate(e.date||o.date)}</td><td><b>${money(e.amount)}</b></td><td>${can(e)?`<button class="btn secondary" onclick="event.stopPropagation();delExtra('${o.id}','${e.id}')">✕</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="muted">No extra costs yet. Add transport, tickets, duty and so on.</div>'}
<div class="muted" style="margin-top:6px">In landed price: <b>${money(inL)}</b>${late?` · Added after receiving: <b>${money(late)}</b> (recorded only, landed prices do not change)`:''}${lock&&!o.corr?' · Landed prices are fixed because stock has been received.':''}</div>
<div style="margin-top:8px"><select class="filter" onchange="extraMenu('${o.id}',this)"><option value="">Extra costs ▾</option><option value="add">＋ Add extra cost</option>${lock&&!o.corr?'<option value="corr">✎ Correct extra costs</option>':''}${o.corr?'<option value="done">✔ Finish correcting</option>':''}</select>${o.corr?' <span class="muted">Correcting: stock already received keeps its landed price.</span>':''}</div>`}
function payHTML(o){if(o.status==='Draft')return '';if(!Array.isArray(o.payments))o.payments=[];const due=Math.round(ordDue(o)),paid=ordPaid(o),owed=due-paid,fn=linkOn()?`openOrderPay('${o.id}','pay')`:`openSimpleSupplierPay('${o.id}')`;return `<div class="form-note" style="margin-top:10px"><b>Supplier account</b> · Total to pay ${money(due)} (items and extra costs) · Paid / credited ${money(paid)} · ${owed>0?`<b style="color:#b43c3c">Still owed ${money(owed)}</b> <button class="btn secondary" onclick="${fn}">Record payment</button>`:owed<0?`<b>Overpaid ${money(-owed)}</b>`:'<b style="color:#1f7a4d">Fully settled</b>'}</div>`}
