function opTopUp(){const sh=opShort(),a=opAmts();state.cashbook=state.cashbook||[];Object.entries(sh).forEach(([m,v])=>state.cashbook.push({id:nextCb(),date:todayKey(),time:nowTime(),dir:'in',cat:'Owner top-up',amount:v,method:m,note:'Top-up for '+window._payId}));payDraft=finMethods().map(m=>a[m]||0);persist();renderAll();openOrderPay(window._payId,window._payMode);toast('Topped up. Balances updated.')}
function opCancel(){const id=window._payId;payDraft=null;pendMO=null;showOrder(id)}
function opConfirm(anyway){const id=window._payId,mode=window._payMode,a=opAmts(),credit=opCredit(),cash=Object.values(a).reduce((x,y)=>x+y,0),o=state.orders.find(x=>x.id===id);if(!o)return;const sup=state.suppliers.find(x=>sk(x.name)===sk(o.supplier));if(credit>supplierCredit(sup||{})||credit>(window._payOwed||0)){toast('Supplier credit exceeds the available credit or the amount owed.');return}if(!anyway&&Object.keys(opShort()).length)return;let nd=null;if(mode==='order'){if(!pendMO)return;nd=commitMarkOrdered(id,pendMO.keep,true)}if(!Array.isArray(o.payments))o.payments=[];state.cashbook=state.cashbook||[];if(credit>0){sup.creditBalance=supplierCredit(sup)-credit;sup.creditLedger=sup.creditLedger||[];sup.creditLedger.push({date:todayKey(),type:'Credit applied',amount:-credit,ref:id});o.payments.push({id:'SC-'+Date.now(),date:todayKey(),method:'Supplier credit',amount:credit})}Object.entries(a).forEach(([m,v])=>{const cid=nextCb();state.cashbook.push({id:cid,date:todayKey(),time:nowTime(),dir:'out',cat:'Supplier payment',amount:v,method:m,note:id+' · '+o.supplier+' (items and extra costs)',order:id});o.payments.push({id:cid,date:todayKey(),method:m,amount:v})});const tot=cash+credit;if(mode==='order')finishOrdered(id,nd,tot?`${id} ordered. ${money(tot)} recorded (${money(cash)} cash and ${money(credit)} supplier credit).`:`${id} ordered. Nothing paid yet, so the full amount is shown as owed.`);else{persist();renderAll();showOrder(id);toast(`${money(tot)} payment recorded.`)}}

function closeOutstandingSummary(o){return (o.lines||[]).flatMap((l,li)=>(l.variants||[]).map((v,vi)=>({li,vi,l,v,qty:Math.max(0,(+v.qty||0)-(+v.recv||0))}))).filter(x=>x.qty>0)}
