function openCloseOutstanding(id){ensureSuppliers();const o=state.orders.find(x=>x.id===id);if(!o||!['Ordered','Part-received'].includes(o.status))return;const a=outstandingSettlement(o);if(!a.lines.length){toast('There are no outstanding quantities to close.');return}showModal('Close outstanding items · '+id,`<div class="form-note">${a.lines.reduce((n,x)=>n+x.qty,0)} pair(s) remain undelivered. Estimated supplier-goods value: <b>${money(a.goods)}</b>. This does not add stock. Choose how the supplier will settle the undelivered goods.</div><div class="form-note" style="margin-top:8px">Cash payments recorded: <b>${money(a.cashPaid)}</b> · Supplier credit applied: <b>${money(a.creditPaid)}</b> · Current amount owed: <b>${money(a.owed)}</b> · Estimated paid portion of undelivered goods: <b>${money(a.creditShare)}</b>.</div><form onsubmit="confirmCloseOutstanding(event,'${id}')"><div class="field"><label>SETTLEMENT OPTION</label><select name="option" id="closeOption" onchange="closeOptionInfo('${id}')"><option value="refund">Supplier refunds the money</option><option value="credit">Supplier gives credit for a future order</option><option value="unpaid">Cancel unpaid balance (no refund)</option></select></div><div class="field"><label>REFUND PAYMENT METHOD (IF REFUNDING)</label><select name="method"><option>Cash</option><option>Bank Transfer</option><option>Airtel Money</option><option>TNM Mpamba</option></select></div><div id="closeOptionInfo" class="form-note"></div><div class="form-actions"><button type="button" class="btn secondary" onclick="showOrder('${id}')">Cancel</button><button class="btn primary">Close outstanding items</button></div></form>`);closeOptionInfo(id)}
function closeOptionInfo(id){const o=state.orders.find(x=>x.id===id),sel=document.getElementById('closeOption'),info=document.getElementById('closeOptionInfo');if(!o||!sel||!info)return;const a=outstandingSettlement(o),opt=sel.value;info.innerHTML=opt==='refund'?`Estimated cash refund supported by recorded cash payments: <b>${money(a.cashShare)}</b>. If some of the order was paid using supplier credit, choose Supplier Credit to return that portion as credit.`:opt==='credit'?`The system will add <b>${money(a.creditShare)}</b> to this supplier's credit balance for a future order. This includes the paid portion originally covered by cash and supplier credit. No Cashbook cash-in is recorded.`:`This option is available only when the unpaid order balance covers the full undelivered goods value (${money(a.goods)}). No refund or supplier credit will be recorded.`}
function confirmCloseOutstanding(e,id){e.preventDefault();const o=state.orders.find(x=>x.id===id),d=formData(e);if(!o||!['Ordered','Part-received'].includes(o.status))return;const a=outstandingSettlement(o);if(!a.lines.length)return;let amount=0;const opt=d.option;let sup=state.suppliers.find(x=>sk(x.name)===sk(o.supplier));if(!sup){ensureSuppliers();sup=state.suppliers.find(x=>sk(x.name)===sk(o.supplier))}if(opt==='refund'){if(a.cashShare<=0){toast('No cash-paid portion is available to refund. Choose supplier credit or cancel the unpaid balance.');return}amount=a.cashShare;state.cashbook=state.cashbook||[];state.cashbook.push({id:nextCb(),date:todayKey(),time:nowTime(),dir:'in',cat:'Supplier refund',amount,method:d.method||'Bank Transfer',note:id+' · refund from '+o.supplier,order:id});o.supplierRefunds=o.supplierRefunds||[];o.supplierRefunds.push({date:todayKey(),amount,method:d.method||'Bank Transfer',ref:id});o.payments=o.payments||[];o.payments.push({id:'SR-'+Date.now(),date:todayKey(),method:'Supplier refund',amount:-amount})}else if(opt==='credit'){if(a.creditShare<=0){toast('No paid portion is available to convert into supplier credit.');return}amount=a.creditShare;sup.creditBalance=supplierCredit(sup)+amount;sup.creditLedger=sup.creditLedger||[];sup.creditLedger.push({date:todayKey(),type:'Credit issued',amount,ref:id});o.payments=o.payments||[];o.payments.push({id:'SC-ISS-'+Date.now(),date:todayKey(),method:'Supplier credit issued',amount:-amount})}else if(opt==='unpaid'){if(a.owed<a.goods){toast('The unpaid order balance does not cover all undelivered goods. Use a refund or supplier credit for the paid portion, or reconcile the order payments.');return}amount=a.goods}else{toast('Choose a settlement option.');return}
const cancelled=a.lines.map(x=>({category:x.l.category,model:x.l.model,variant:x.v.color+' · '+x.v.size,qty:x.qty,unitCost:x.l.unitCost}));a.lines.forEach(x=>{x.v.cancelledQty=(+x.v.cancelledQty||0)+x.qty;x.v.qty=x.v.recv||0});o.lines.forEach(l=>l.qty=(l.variants||[]).reduce((n,v)=>n+(+v.qty||0),0));o.closures=o.closures||[];o.closures.push({date:todayKey(),option:opt,amount,method:d.method||'',lines:cancelled});o.status='Closed';activity('Outstanding order items closed',id,o.supplier,`${cancelled.reduce((n,x)=>n+x.qty,0)} pair(s) cancelled · ${opt} · ${money(amount)}`);persist();renderAll();showOrder(id);toast(`Outstanding items closed. ${cancelled.reduce((n,x)=>n+x.qty,0)} pair(s) were not added to stock.`)}

function closureHTML(o){if(!(o.closures||[]).length)return '';return `<h3 style="margin:14px 0 8px;font-size:14px">Closed outstanding items</h3>${o.closures.map(c=>`<div class="form-note">${fmtDate(c.date)} · ${c.option==='refund'?'Supplier refund':c.option==='credit'?'Supplier credit':'Unpaid balance cancelled'} · <b>${money(c.amount)}</b><div class="muted">${c.lines.map(x=>`${esc(x.model)} ${esc(x.variant)}: ${x.qty}`).join(' · ')}</div></div>`).join('')}`}

