function ymd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function periodList(type){const now=new Date(todayKey()+'T00:00:00'),out=[];
if(type==='week'){const d0=new Date(now);d0.setDate(d0.getDate()-((d0.getDay()+6)%7));for(let i=0;i<12;i++){const a=new Date(d0);a.setDate(d0.getDate()-7*i);const b=new Date(a);b.setDate(a.getDate()+6);out.push({label:'Week of '+fmtDate(ymd(a))+' to '+fmtDate(ymd(b)),from:ymd(a),to:ymd(b)})}}
else if(type==='month'){for(let i=0;i<12;i++){const a=new Date(now.getFullYear(),now.getMonth()-i,1),b=new Date(a.getFullYear(),a.getMonth()+1,0);out.push({label:MONTHS[a.getMonth()]+' '+a.getFullYear(),from:ymd(a),to:ymd(b)})}}
else if(type==='quarter'){const base=now.getFullYear()*4+Math.floor(now.getMonth()/3);for(let i=0;i<8;i++){const ix=base-i,y=Math.floor(ix/4),q=ix%4,a=new Date(y,q*3,1),b=new Date(y,q*3+3,0);out.push({label:'Q'+(q+1)+' '+y+' ('+MONTHS[q*3].slice(0,3)+' to '+MONTHS[q*3+2].slice(0,3)+')',from:ymd(a),to:ymd(b)})}}
else{for(let i=0;i<5;i++){const y=now.getFullYear()-i;out.push({label:String(y),from:y+'-01-01',to:y+'-12-31'})}}
return out}
